COLLDATA("sh10757","ar",[[7592,"٢٣٢٧ - «هذا الموقف وعرفة كلها موقف» .\n(صحيح) [هـ] عن علي. حجاب المرأة ٢٧."],[7593,"«هذا الوضوء فمن زاد على هذا فقد أساء أو تعدى وظلم» .\n(حسن) [حم هـ] عن ابن عمرو. تمام المنة، صحيح أبي داود ١٢٤."],[7594,"٢٣٢٨ - «هذا أوان يختلس العلم من الناس حتى لا يقدروا منه على شيء ثكلتك أمك يا زياد! إن كنت لأعدك من فقهاء أهل المدينة هذه التوراة والإنجيل عند اليهود والنصارى فماذا يغني عنهم؟!» .\n(صحيح) [ت ك] عن أبي الدرداء [حم هـ ك] عن زياد بن لبيد. اقتصاد العلم ٨٩."],[7595,"٢٣٢٩ - «هذا جبريل آخذ برأس فرسه عليه أداة الحرب» .\n(صحيح) [خ] عن ابن عباس. خ: المغازي."],[7596,"٢٣٣٠ - «هذا جبل يحبنا ونحبه» .\n(صحيح) [ق ت] عن أنس."],[7597,"٢٣٣١ - «هذا حجر رمي به في النار منذ سبعين خريفا فلهو يهوي في النار الآن حين انتهى إلى قعرها» .\n(صحيح) [حم م] عن أبي هريرة. م ختصر مسلم ١٩٧٧."],[7598,"٢٣٣٢ - «هذا خالي فليرني امرؤ خاله» .\n(صحيح) [ت ك] عن جابر. المشكاة ٦١٢٧."],[7599,"٢٣٣٣ - «هذا شهر رمضان قد جاءكم تفتح به أبواب الجنة وتغلق فيه أبواب النار وتسلسل فيه الشياطين» .\n(صحيح) [حم ن] عن أنس. صحيح الترغيب ٢/٦٩: ق - أبي هريرة١."],[7600,"(١) ومضى حديثه برقم ٥٢٨."],[7601,"٢٣٣٤ - «هذا قزح وهو الموقف وجمع كلها موقف ونحرت هاهنا ومنى كلها منحر فانحروا في رحالكم» .\n(صحيح) [د] عن علي. حجاب المرأة ص ٢٧: حم، عم، الضياء."],[7602,"٢٣٣٥ - «هذا قزح وهو الموقف جمع كلها موقف هذا المنحر ومنى كلها منحر» .\n(صحيح) [ت] عن علي. المصدر نفسه."],[7603,"٢٣٣٦ - «هذا ممن قضى نحبه» . - يعني طلحة -.\n(صحيح) [ت] عن طلحة. الصحيحة ١٢٥: ع، طب، الضياء."],[7604,"٢٣٣٧ - «هذا مني - يعني الحسن - وحسين من علي» .\n(صحيح) [د] عن المقدام بن معد يكرب. الضعيفة ٤٧٢٢: حم."],[7605,"٢٣٣٨ - «هذا موضع الإزار فإن أبيت فأسفل فإن أبيت فلا حق للإزار فيما دسون الكعبين» .\n(صحيح) [حم ت ن هـ] عن حذيفة. الصحيحة ١٧٦٥: الحميدي."],[7606,"٢٣٣٩ - «هذا والذي نفسي بيده من النعيم الذي تسألون عنه: ظل بارد ورطب طيب وماء بارد» .\n(صحيح) [ت] عن أبي هريرة. الروض النضير ٤٥٣، الترغيب ٣/١٢٨ - ١٢٩: حب، طص - ابن عباس. ك - عمر."],[7607,"٢٣٤٠ - «هذا يوم عاشوراء ولم يكتب الله عليكم صيامه وأنا صائم فمن شاء فليصم ومن شاء فليفطر» .\n(صحيح) [ق] عن معاوية."],[7608,"«هذان ابناى وابنا بنتي اللهم إني أحبهما فأحبهما وأحب من يحبهما» .\n(حسن) [ت حب] عن أسامة بن زيد. المشكاة ٦١٥٦."],[7609,"٢٣٤٢ - «هذان السمع والبصر» - يعني أبا بكر وعمر -.\n(صحيح) [ت ك] عن عبد الله بن حنطب. الصحيحة ٨١٤."],[7610,"٢٣٤٣ - «هذان سيدا كهول أهل الجنة من الأولين والآخرين إلا النبيين والمرسلين لا تخبرهما يا علي» - يعني أبا بكر وعمر -.\n(صحيح) [ت] عن أنس وعلي. الصحيحة ٨٢٢."],[7611,"«هذه النار جزء من مائة جزء من جهنم» .\n(صحيح) [حم] عن أبي هريرة. الترغيب ٤/٢٢٧."],[7612,"٢٣٤٤ - «هذه بتلك السبقة» .\n(صحيح) [حم د] عن عائشة. آداب الزفاف ص ١٧١: حم، الحميدي، ن، هـ."],[7613,"٢٣٤٥ - «هذه ثم ظهور الحصر» - قاله صلى الله عليه وآله وسلم لأزواجه في حجة الوداع - ... [خ د] عن أبي واقد.\n(صحيح) الصحيحة ٢٤٠١: طب، ابن عساكر. حم، ابن سعد - أبي هريرة وزينب وسودة. ع - أم سلمة. طس - ابن عمر."],[7614,"٢٣٤٦ - «هذه رحمة يجعلها الله في قلوب من يشاء من عباده وإنما يرحم الله من عباده الرحماء» .\n(صحيح) [حم ق د ن هـ] عن أسامة بن زيد. أحكام الجنائز ١٦٤."],[7615,"٢٣٤٧ - «هذه صلاة البيوت» - يعني السبحة بعد المغرب -.\n(صحيح) [د] عن كعب بن عجرة. صحيح أبي داود ١١٧٦."],[7616,"٢٣٤٨ - «هذه طابة وهذا أحد وهو جبل يحبنا ونحبه» .\n(صحيح) [حم ق] عن أبي حميد. مختصر مسلم ١٥٤٣."],[7617,"٢٣٤٩ - «هذه عرفة وهو الموقف وعرفة كلها موقف» .\n(صحيح) [ت] عن علي. حجاب المرأة ص ٢٧، حم، عم، الضياء."],[7618,"٢٣٥٠ - «هذه عمرة استمتعنا بها فمن لم يكن عنده الهدي فليحل الحل كله فإن العمرة قد دخلت في الحج إلى يوم القيامة» .\n(صحيح) [حم م] عن ابن عباس. الإرواء ٩٨٢."],[7619,"٢٣٥١ - «هذه وهذه سواء» - يعني الخنصر والإبهام -.\n(صحيح) [حم خ ت ن هـ] عن ابن عباس."],[7620,"«هكذا الوضوء فمن زاد على هذا ... فقد أساء وظلم» .\n(حسن) [حم د ن هـ] عن ابن عمرو. صحيح أبي داود ١٢٤."],[7621,"٢٣٥٣ - «هكذا فإنما الاستئذان من النظر» .\n(صحيح) [د] عن سعد. الترغيب ٣/٢٧٣: ق - سهل١."],[7622,"٢٣٥٤ - «هاهنا أحد من بني فلان؟ إن صاحبكم مأسور بدينه» .\n(صحيح) [حم د] عن سمرة. أحكام الجنائز ص ١٥: الطيالسي، ق، ك، هق."],[7623,"٢٣٥٥ - «هاهنا أرض الفتن حيث يطلع قرن الشيطان» .\n(صحيح) [ت] عن ابن عمر. حم ٢/٢٣و ٩٢و ١١١و ١٢١، ق: فتن."],[7624,"«هجاهم حسان فشفى واشتفى٢» .\n(صحيح) [م] عن عائشة. م ٧/١٦٥."],[7625,"«هجر المسلم أخاه كسفك دمه» .\n(صحيح) [ابن قانع] عن أبي حدرد. شاهد في الأحاديث الصحيحة ٩٢٨."],[7626,"(١) ومضى حديثه برقم ٢٣٥٤.٢ الأصل واستشفى [، والصواب ما أثبته، المعنى] فشفى المؤمنين واستشفى\" أي هو بما ناله من أعراض الكفار ومزقها."],[7627,"«هدايا العمال غلول» .\n(صحيح) [حم هق] عن أبي حميد الساعدي. الإرواء ٢٦٢٢."],[7628,"٢٣٥٦ - «هدم المتعة النكاح والطلاق والعدة والميراث» .\n(حسن) [حب] عن أبي هريرة. الصحيحة ٢٤٠٢: قط، هق."],[7629,"٢٣٥٧ - «هل أنت إلا إصبع دميت وفي سبيل الله ما لقيت» .\n(صحيح) [حم ق ت ن] عن جندب البجلي. مختصر مسلم ١١٦٦."],[7630,"٢٣٥٨ - «هل أنتم تاركوا لي أمرائي؟ لكم صفوة أمرهم وعليهم كدره» .\n(صحيح) [د] عن عوف بن مالك. الإرواء ١٢١١."],[7631,"٢٣٥٩ - «هل أنتم تاركوا لي أمرائي؟ إنما مثلكم ومثلهم كمثل رجل استرعى إبلا أو غنما فرعاها ثم تحين سقيها فأوردها حوضا فشرعت فيه فشربت صفوه وتركت كدره فصفوه لكم وكدره عليهم» .\n(صحيح) [م] عن عوف بن مالك. الإرواء ١٢١١."],[7632,"٢٣٦٠ - «هل تدرون أين تغرب هذه؟ تغرب في عين حامية» .\n(صحيح) [د] عن أبي ذر. الصحيحة ٢٤٠٣: حم."],[7633,"٢٣٦١ - «هل تدرون ما الكوثر؟ هونهر أعطانيه ربي في الجنة عليه خير كثير ترد عليه أمتي يوم القيامة آنيته عدد الكواكب يختلج العبد منهم فأقول: يا رب أنه من أمتي فيقال: إنك لا تدري ما أحدثوا بعدك» .\n(صحيح) [حم م د ن] عن أنس. السنة ٧٦٤: ابن أبي عاصم."],[7634,"٢٣٦٢ - \"هل تدرون ماذا قال ربكم الليلة؟ قال الله: أصبح من عبادي مؤمن بي وكافر فأما من قال: مطرنا بفضل الله ورحمته فذلك مؤمن بي كافر بالكواكب وأما من قال: مطرنا بنوء كذا وكذا فذلك كافر بي ومؤمن بالكواكب\".\n(صحيح) [حم ق د ن هـ] عن زيد بن خالد. مختصر مسلم ٥٦، الإرواء ٦٨١."],[7635,"٢٣٦٣ - «هل ترون قبلتي هاهنا؟ فوالله ما يخفي على خشوعكم ولا ركوعكم إني لأراكم من وراء ظهري» .\n(صحيح) [مالك ق] عن أبي هريرة."],[7636,"٢٣٦٤ - «هل ترون ما أرى؟ إني لأرى مواقع الفتن خلال بيوتكم كمواقع القطر» .\n(صحيح) [حم ق] عن أسامة. مختصر مسلم ١٩٨٩."],[7637,"٢٣٦٥ - \"هل تضارون في رؤية الشمس بالظهيرة صحوا ليس معها سحاب؟ وهل تضارون في رؤية القمر ليلة البدر صحوا ليس فيها سحاب؟ ما تضارون في رؤية الله يوم القيامة إلا كما تضارون في رؤية أحدهما إذا كان يوم القيامة أذن مؤذن: ليتبع كل أمة ما كانت تعبد فلا يبقى أحد كان يعبد غير الله من الأصنام والأنصاب إلا يتساقطون في النار حتى إذا لم يبق إلا من كان يعبد الله من بر وفاجر وغير أهل الكتاب فيدعى اليهود فيقال لهم: ما كنتم تعبدون؟ قالوا: كنا نعبد عزيرا ابن الله! فيقال: كذبتم ما اتخذ الله من صاحبة ولا ولد فماذا تبغون؟ قالوا: عطشنا يا ربنا فاسقنا فيشار إليهم: ألا تردون؟ فيحشرون إلى النار كأنها سراب يحطم بعضها بعضا فيتساقطون في النار ; ثم يدعى النصارى فيقال لهم: ما كنتم تعبدون؟ قالوا: كنا نعبد المسيح ابن الله! فيقال لهم: كذبتم ما اتخذ الله من صاحبة ولا ولد فيقال لهم: ماذا تبغون؟ فيقولون: عطشنا يا ربنا فاسقنا فيشار إليهم: ألا تردون؟ فيحشرون إلى جهنم كأنها سراب يحطم بعضها بعضا فيتساقطون في النار حتى إذا لم يبق إلا من كان يعبد الله من بر وفاجر أتاهم رب العالمين في أدنى صورة من التي رأوه فيها قال: فما تنتظرون؟ تتبع كل أمة ما كانت تعبد قالوا: يا ربنا فارقنا الناس في الدنيا أفقر ما كنا إليهم ولم نصاحبهم فيقول: أنا ربكم قيقولون: نعوذ بالله منك لا نشرك بالله شيئا مرتين أو ثلاثا حتى إن بعضهم ليكاد أن ينقلب فيقول: هل بينكم وبينه آية فتعرفونه بها؟ فيقولون: نعم الساق فيكشف عن ساق فلا يبقي من كان يسجد لله من تلقاء نفسه إلا أذن الله له بالسجود ولا يبقى من كان يسجد اتقاء ورياء إلا جعل الله ظهره طبقة واحدة كلما أراد أن يسجد خر على قفاه ثم يرفعون رءوسهم وقد تحول في الصورة التي رأوه فيها أول مرة فيقول: أنا ربكم فيقولون: أنت ربنا ; ثم يضرب الجسر على جهنم وتحل الشفاعة ويقولون: اللهم سلم سلم قيل: يا رسول الله وما الجسر؟ قال: دحض مزلة فيه خطاطيف وكلاليب وحسكة تكون بنجد فيها شويكة يقال لها: السعدان فيمر المؤمنون كطرف العين وكالبرق وكالريح وكالطير وكأجأويد الخيل والركاب فناج مسلم ومخدوش مرسل ومكدوس في نار جهنم حتى إذا خلص المؤمنون من النار فوالذي نفسي بيده ما من أحد منكم بأشد مناشدة لله في استيفاء الحق من المؤمنين لله يوم القيامة لإخوانهم الذين في النار يقولون: ربنا كانوا يصومون معنا ويصلون ويحجون فيقال لهم: أخرجوا من عرفتم فتحرم صورهم على النار فيخرجون خلقا كثيرا قد أخذت النار إلى نصف ساقه وإلى ركبتيه قيقولون: ربنا ما بقي فيها أحد ممن أمرتنا به ; فيقول الله عز وجل: ارجعوا فمن وجدتم في قلبه مثقال دينار من خير فأخرجوه فيخرجون خلقا كثيرا ثم يقولون ربنا لم نذر فيها أحدا ممن أمرتنا به ; ثم يقول: ارجعوا فمن وجدتم في قلبه مثقال نصف دينار من خير فأخرجوه فيخرجون خلقا كثيرا ثم يقولون: ربنا لم نذر فيها ممن أمرتنا أحدا ثم يقول: ارجعوا فمن وجدتم في قلبه مثقال ذرة من خير فأخرجوه فيخرجون خلقا كثير ثم يقولون: ربنا! لم نذر فيها خيرا فيقول الله: شفعت الملائكة وشفع النبيون وشفع المؤمنون ولم يبق إلا أرحم الراحمين فيقبض قبضة من النار فيخرج منها قوما لم يعملوا خير قط قد عادوا حمما فيلقيهم في نهر في أفواه الجنة يقال له: نهر الحياة فيخرجون كما تخرج الحبة في حميل السيل ألا ترونها تكون إلى الحجر أو الشجر ما يكون إلى الشمس أصيفر وأخيضر وما يكون منها إلى الظل يكون أبيض فيخرجون كاللؤلؤ في رقابهم الخواتيم يعرفهم أهل الجنة: هؤلاء عتقاء الله من النار الذين أدخلهم الجنة بغير عمل عملوه ولا خير قدموه ثم يقول: أدخلوا الجنة فما رأيتموه فهو لكم فيقولون: ربنا أعطيتنا ما لم تعط أحدا من العالمين فيقول: لكم عندي أفضل من هذا؟ فيقولون: يا ربنا أي شيء أفضل من هذا؟ فيقول: رضاي فلا أسخط عليكم بعده أبدا\".\n(صحيح) [حم ق] عن أبي سعيد. حم ٣/١١ - ١٦ - ١٧، خ: الرقاق، م، الايمان."],[7638,"٢٣٦٦ - \"هل تضارون في رؤية الشمس في الظهيرة ليست في سحابة؟ هل تضارون في رؤية القمر ليلة البدر ليس في سحابة؟ فوالذي نفسي بيده لا تضارون في رؤية ربكم عز وجل إلا كما تضارون في رؤية أحدهما فيلقى العبد فيقول: أي فل ألم أكرمك وأسودك وأزوجك وأسخر لك الخيل والإبل وأذرك ترأس وتربع؟ فيقول: بلى أي رب فيقول: أفظننت أنك ملاقي؟ فيقول: لا فيقول: إني أنساك كما نسيتني; ثم يلقى الثاني فيقول له: أي فل؟ ألم أكرمك وأسودك وأزوجك وأسخر لك الخيل والإبل وأذرك ترأس وتربع؟ فيقول: بلى أي رب! فيقول: أفظننت أنك ملاقي؟ فيقول: لا فيقول: إني أنساك كما نسيتني; ثم يلقى الثالث فيقول له مثل ذلك فيقول: رب آمنت بك وبكتابك وبرسلك وصليت وصمت وتصدقت ويثني بخير ما استطاع فيقول: هاهنا إذن ثم يقال: الآن نبعث شاهدا عليك ويتفكر في نفسه: من ذا الذي يشهد علي؟ فيختم على فيه ويقال لفخذه: انطقي فتنطق فخذه ولحمه وعظامه بعمله وذلك ليعذر من نفسه وذلك المنافق الذي يسخط الله عليه\".\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ١٩٣٢."],[7639,"٢٣٦٧ - \"هل تمارون في القمر ليلة البدر ليس دونه سحاب؟ هل تمارون في رؤية الشمس ليس دونها سحاب؟ فإنكم ترونه كذلك يحشر الله الناس يوم القيامة فيقول: من كان يعبد شيئا فليتبعه فيتبع من كان يعبد الشمس الشمس ويتبع من كان يعبد القمر القمر ويتبع من كان يعبد الطواغيت الطواغيت وتبقى هذه الأمة فيها منافقوها; فيأتيهم الله في صورة غير صورته التي يعرفون فيقول: أنا ربكم فيقولون: نعوذ بالله منك هذا مكاننا حتى يأتينا ربنا فإذا جاءنا عرفناه فيأتيهم الله في صورته التي يعرفون فيقول: أنا ربكم فيقولون: أنت ربنا فيتبعونه; ويضرب الصراط بين ظهراني جهنم فأكون أول من يجوز من الرسل بأمته ولا يتكلم يومئذ أحد إلا الرسل وكلام الرسل يومئذ: اللهم سلم سلم وفي جهنم كلاليب مثل شوك السعدان غير أنه لا يعلم ما قدر عظمها إلا الله تخطف الناس بأعمالهم فمنهم من يوبق بعمله ومنهم من يخردل ثم ينجوحتى إذا فرغ الله من القضاء بين العباد وأراد أن يخرج برحمته من أراد من أهل النار أمر الملائكة أن يخرجوا من النار من كان لا يشرك بالله شيئا ممن يقول لا إله إلا الله فيخرجونهم ويعرفونهم بآثار السجود وحرم الله على النار أن تأكل آثار السجود فيخرجون من النار وقد امتحشوا فيصب عليهم ماء الحياة فينبتون كما تنبت الحبة في حميل السيل ثم يفرغ الله من القضاء بين العباد ويبقى رجل بين الجنة والنار وهو آخر أهل النار دخولا الجنة مقبلا بوجهه قبل النار فيقول: يا رب اصرف وجهي عن النار فقد قشبني ريحها وأحرقني ذكاؤها فيقول: هل عسيت إن فعل ذلك بك أن تسأل غير ذلك فيقول: لا وعزتك فيعطي الله ما يشاء من عهد وميثاق، فيصرف الله وجهه عن النار فإذا أقبل به على الجنة ورأى بهجتها سكت ما شاء الله أن يسكت ثم قال: يا رب! قدمني عند باب الجنة فيقول الله: أليس قد أعطيت العهد والميثاق أن لا تسأل غير الذي كنت سألت؟ فيقول: يا رب لا أكون أشقى خلقك فيقول: فما عسيت إن أعطيتك ذلك أن لا تسأل غيره؟ فيقول لا وعزتك لا أسألك غير ذلك فيعطى ربه ما شاء من عهد وميثاق فيقدمه إلى باب الجنة فإذا بلغ بابها فرأى زهرتها وما فيها من النضرة والسرور ; فيسكت ما شاء الله أن يسكت فيقول: يا رب أدخلني الجنة فيقول الله: ويحك يا ابن آدم! ما أغدرك! أليس قد أعطيت العهد والميثاق أن لا تسأل غير الذي أعطيت؟ فيقول: يا رب لا تجعلني أشقى خلقك فيضحك الله منه ثم يأذن له في دخول الجنة فيقول: تمن فيتمني حتى إذا انقطعت أمنيته قال الله تعالى: زد من كذا وكذا أقبل يذكره ربه حتى إذا انتهت به الأماني قال الله عز وجل: لك ذلك ومثله معه\".\n(صحيح) [حم ق] عن أبي هريرة وأبي سعيد لكنه قال: وعشرة أمثاله. حم ٢/٢٩٣ - ٢٩٤، خ: الأذان، الرقاق، مختصر مسلم ٨٦: الايمان."],[7640,"٢٣٦٨ - «هل تنصرون إلا بضعفائكم؟ بدعوتهم وإخلاصهم» .\n(صحيح) [حل] عن سعد. صحيح الترغيب ٥: ن١."],[7641,"«هل تنصرون وترزقون إلا بضعفائكم؟» .\n(صحيح) [خ] عن سعد. خ: الجهاد ٧٦."],[7642,"٢٣٦٩ - \"هل قرأ معي أحد منكم آنفا؟ إني أقول: مالي أنازع القرآن؟!.\n(صحيح) [حم ت ن هـ حب] عن أبي هريرة. صفة الصلاة ٨٠."],[7643,"(١) مضى لفظه برقم ٢٣٨٨."],[7644,"٢٣٧٠ - «هل منكم رجل إذ أتى أهله فأغلق عليه بابه وألقى عليه ستره واستتر بستر الله؟ قالوا: نعم قال: ثم يجلس بعد ذلك فيقول: فعلت كذا فعلت كذا فسكتوا ثم أقبل على النساء فقال: هل منكن من تحدث١؟ فسكتن فجثت فتاة كعاب على إحدى ركبتيها وتطأولت لرسول الله صلى الله عليه وآله وسلم ليراها ويسمع كلامها فقالت: يا رسول الله! إنهم ليحدثون وإنهن ليحدثن فقال: هل تدرون ما مثل ذلك؟ إنما مثل ذلك مثل شيطانة لقيت شيطانا في السكة فقضى حاجته والناس ينظرون إليه! ألا إن طيب الرجال ما ظهر ريحه ولم يظهر لونه ألا إن طيب النساء ما ظهر لونه ولم يظهر ريحه ألا لا يفضين رجل إلى رجل ولا امرأة إلى امرأة إلا إلى ولد أو والد» .\n(صحيح) [د] عن أبي هريرة. الإرواء ٢٠١١: حم."],[7645,"«هلاك أمتي على يدي غلمة من قريش» .\n(صحيح) [حم خ] عن أبي هريرة. الروض النضير ١١٥٧."],[7646,"«هلك المتنطعون» .\n(صحيح) [حم م د] عن ابن مسعود. غاية المرام ٧."],[7647,"٢٣٧١ - «هلك كسرى ثم لا يكون كسرى بعده وقيصر ليهلكن ثم لا يكون قيصر بعده وليقسمن كنوزهما في سبيل الله» .\n(صحيح) [م] عن أبي هريرة. المشكاة ٥٤١٨، م ٨/١٨٦ - ١٨٧: حم ٢/٢٣٣، ٢٤٠، ٢٥٦، ٢٧٢، ٣١٣، ٤٣٧. خ ٢/٢٥٤."],[7648,"٢٣٧٢ - «هلا أخذتم إهابها فدبغتموه فانتفعتم به؟ إنما حرم أكلها» .\n(صحيح) [حم م ٤] عن ابن عباس. مختصر مسلم ١١٧."],[7649,"(١) الأصل تحدثن. والتصويب من [حم، د] ."],[7650,"٢٣٧٣ - «هلا تركتموه لعله أن يتوب فيتوب الله عليه» .؟ - يعني ماعزا -.\n(صحيح) [د ك] عن نعيم بن هذال. الإرواء ٢٣٢٢، المشكاة ٣٥٦٥."],[7651,"٢٣٧٤ - «هلم إلى الغداء المبارك» - يعني السحور -.\n(صحيح) [حم د ن حب] عن العرباض. صحيح الترغيب ١٠٥٩: المشكاة ١٩٩٧: ابن خزيمة."],[7652,"٢٣٧٥ - «هلم إلى جهاد لا شوكة فيه: الحج» .\n(صحيح) [طب] عن الحسين. الإرواء ٩٦٣، الترغيب ٢/١٠٦."],[7653,"٢٣٧٦ - «هما ريحانتاي من الدنيا» - يعني الحسن والحسين -.\n(صحيح) [حم خ] عن ابن عمر."],[7654,"٢٣٧٧ - «هم الأخسرون ورب الكعبة هم الأخسرون ورب الكعبة يوم القيامة الأكثرون إلا من قال في عباد الله هكذا وهكذا وقليل ما هم والذي نفسي بيده ما من رجل يموت يترك غنما أو إبلا أو بقرا لم يؤد زكاتها إلا جاءته يوم القيامة أعظم ما يكون وأسمنه حتى تطأه بأظلافها وتنطحه بقرونها حتى يقضي بين الناس كلما تقدمت أخراها عادت أولاها» .\n(صحيح) [حم ق ت ن هـ] عن أبي ذر."],[7655,"٢٣٧٨ - «هو اختلاس يختلسه الشيطان من صلاة العبد» - يعني الالتفات -.\n(صحيح) [حم خ د ن] عن عائشة. صحيح أبي داود ٨٤٤، الإرواء ٣٧٠."],[7656,"٢٣٧٩ - «هو الطهور ماؤه الحل ميتته» .\n(صحيح) [حم ٤ حب ك] عن أبي هريرة [حم هـ حب ك] عن جابر [هـ] عن ابن الفراسي. صحيح أبي داود ٧٦، الصحيحة ٤٨٠، الإرواء ٩."],[7657,"٢٣٨٠ - «هو حر كله ليس لله شريك» .\n(صحيح) [حم د ن] عن والد أبي المليح. المشكاة ٣٣٩٧، الإرواء ١٥٢٢."],[7658,"٢٣٨١ - «هو عليها صدقة وهو منها لنا هدية» .\n(صحيح) [حم ق د ن] عن أنس [ق] عن عائشة. مختصر مسلم ٨٩٧."],[7659,"٢٣٨٢ - «هو في ضحضاح من نار ولولا أنا لكان في الدرك الأسفل من النار» - يعني أبا طالب -.\n(صحيح) [ق] عن العباس. الصحيحة ٥٥: حم، ع، ابن عساكر."],[7660,"٢٣٨٣ - «هون عليك فإني لست بملك إنما أنا ابن امرأة من قريش كانت تأكل القديد» .\n(صحيح) [هـ ك] عن أبي مسعود البدري [ك] عن جرير. الصحيحة ١٨٧٦: طس - جرير. ابن سعد - قيس بن أبي حازم مرسلا."],[7661,"فصل في المحلى بـ\"ال\" من هذا الحرف."],[7662,"٢٣٨٤ - «الهجرة هجرتان: هجرة الحاضر وهجرة البادي فأما البادي فيجيب إذا دعي ويطيع إذا أمر وأما الحاضر فهو أعظمهما بلية وأعظمهما أجرا» .\n(صحيح) [ن] عن ابن عمرو. الصحيحة ١٤٦٢."],[7663,"«الهدية إلى الإمام غلول» ١.\n(صحيح) [طب] عن ابن عباس. الإرواء ٢٦٢٢."],[7664,"(١) تكرر هذا اللفظ في الغنيمة قبل القسمة. وهو يشمل كل من خان في شيء خفية، ولم يسم سرقة لأن للآخذ شبهة تملك لنصيب منه، ولكن يده مغلولة عنه حتى تتم القسمة - ز -."],[7665,"حرف الواو."],[7666,"«والشاة إن رحمتها يرحمك الله» .\n(صحيح) [طب] عن قرة بن إياس ومعقل بن يسار. الروض النضير ٨٣٨، الصحيحة ٢٦."],[7667,"٢٣٨٥ - «والذي نفس محمد بيده إن على الأرض من مؤمن إلا وأنا أولى الناس به فأيكم ما ترك دينا أو ضياعا فأنا مولاه وأيكم ما ترك مالا فإلى العصبة من كان» .\n(صحيح) [م] عن أبي هريرة. أحكام الجنائز ص ٨٦: حم."],[7668,"٢٣٨٦ - «والذي نفس محمد بيده إني لأرجوأن تكونوا نصف أهل الجنة وذلك أن الجنة لا يدخلها إلا نفس مسلمة وما أنتم في أهل الشرك إلا كالشعرة البيضاء في جلد الثور الأسود أو كالشعرة السوداء في جلد الثور الأحمر» .\n(صحيح) [ق] عن ابن مسعود."],[7669,"٢٣٨٧ - «والذي نفس محمد بيده لغفار وأسلم ومزينة وجهينة ومن كان من مزينة خير عند الله يوم القيامة من أسد وطيئ وغطفان» .\n(صحيح) [ت] عن أبي هريرة. م ٧/١٧٩."],[7670,"٢٣٨٨ - «والذي نفس محمد بيده لمناديل سعد بن معاذ في الجنة أحسن من هذا» .\n(صحيح) [حم ق] عن أنس [حم ق ت ن] عن البراء."],[7671,"٢٣٨٩ - «والذي نفس محمد بيده ليأتين على أحدكم يوم ولأن يراني ثم لأن يراني أحب إليه من أهله وماله معهم» .\n(صحيح) [حم م] عن أبي هريرة. حم ٢/٣١٣، مختصر مسلم ١٦٠٣."],[7672,"٢٣٩٠ - «والذي نفس محمد بيده ما أصبح عند آل محمد صاع حب ولا صاع تمر» .\n(صحيح) [هـ] عن أنس. الصحيحة ٢٤٠٤: حم، خ، ت."],[7673,"٢٣٩١ - «والذي نفس محمد بيده ما من عبد يؤمن ثم يسدد إلا سلك به في الجنة وأرجوأن لا يدخلها أحد حتى تبوءوا أنتم ومن صلح من ذرياتكم مساكن في الجنة ولقد وعدني ربي أن يدخل الجنة من أمتي سبعين ألفا بغير حساب» .\n(صحيح) [هـ] عن رفاعة الجهني. الصحيحة ٢٤٠٥: الطيالسي، حم، ابن خزيمة، حب."],[7674,"٢٣٩٢ - «والذي نفس محمد بيده لا يسمع بي أحد من هذه الأمة لا يهودي ولا نصراني ثم يموت ولم يؤمن بالذي أرسلت به إلا كان من أصحاب النار» .\n(صحيح) [حم م] عن أبي هريرة. مختصر مسلم ٢٠، الصحيحة ١٥٧: ابن منده."],[7675,"٢٣٩٣ - «والذي نفسي بيده إن السقط ليجر أمه بسرره إلى الجنة إذا احتسبته» .\n(حسن) [هـ] عن معاذ. الترغيب ٣/٩٢: حم."],[7676,"٢٣٩٤ - «والذي نفسي بيده إن الشملة التي أصابها يوم خيبر من المغانم لم تصبها المقاسم لتشتعل عليه نارا» .\n(صحيح) [ق د ن] عن أبي هريرة."],[7677,"٢٣٩٥ - \"والذي نفسي بيده لآنيته - يعني الحوض - أكثر من عدد نجوم السماء وكواكبها في الليلة المظلمة المصحية آنية الجنة من شرب منها ليس يظمأ آخر ما عليه يشخب فيه ميزابان من الجنة من شرب منه لم يظمأ عرضه مثل طوله ما بين عمان إلى أيلة ماؤه أشد بياضا من اللبن وأحلى من العسل\".\n(صحيح) [حم م ت] عن أبي ذر. مختصر مسلم ١٥٥٣."],[7678,"٢٣٩٦ - «والذي نفسي بيده لأذودن رجالا عن حوضي كما تذاد الغريبة من الإبل عن الحوض» .\n(صحيح) [خ] عن أبي هريرة. السنة ٧٦٩: حم، م. ابن أبي عاصم."],[7679,"٢٣٩٧ - «والذي نفسي بيده لأقضين بينكما بكتاب الله الوليدة والغنم رد عليك وعلى ابنك جلد مائة وتغريب عام وعلى امرأة هذا الرجم واغد يا أنيس على امرأة هذا فإن اعترفت فارجمها» .\n(صحيح) [حم ق ٤] عن أبي هريرة وزيد بن خالد الجهني. الإرواء ١٤٦٤."],[7680,"٢٣٩٨ - «والذي نفسي بيده لأن يأخذ أحدكم حبله فيحتطب على ظهره خير له من أن يأتي رجلا فيسأله أعطاه أو منعه» .\n(صحيح) [مالك خ ن] عن أبي هريرة."],[7681,"٢٣٩٩ - «والذي نفسي بيده لتأمرن بالمعروف ولتنهون عن المنكر أو ليوشكن الله أن يبعث عليكم عقابا من عنده ثم لتدعنه فلا يستجيب لكم» .\n(حسن) [حم ت] عن حذيفة. المشكاة ٥١٤٠."],[7682,"٢٤٠٠ - «والذي نفسي بيده لتسألن عن هذا النعيم يوم القيامة أخرجكم من بيوتكم الجوع ثم لم ترجعوا حتى أصابكم هذا النعيم» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ١٣٠٦."],[7683,"٢٤٠١ - \"والذي نفسي بيده لقد هممت أن آمر بحطب فيحطب ثم آمر بالصلاة ليؤذن لها ثم آمر رجلا فيؤم الناس ثم أخالف إلى رجال فأحرق عليهم بيوتهم والذي نفسي بيده لويعلم أحدهم أنه يجد عرقا سمينا أو مرماتين حسنتين لشهد العشاء\".\n(صحيح) [مالك خ ن] عن أبي هريرة."],[7684,"٢٤٠٢ - «والذي نفسي بيده لوكنتم تكونون في بيوتكم على الحالة التي تكونون عليها عندي لصافحتكم الملائكة ولأظلتكم بأجنحتها ولكن يا حنظلة! ساعة وساعة» .\n(صحيح) [حم م ت هـ] عن حنظلة الأسدي. الصحيحة ١٩٤٨."],[7685,"٢٤٠٣ - «والذي نفسي بيده لولم تذنبوا لذهب الله بكم ولجاء بقوم يذنبون فيستغفرون الله فيغفر لهم» .\n(صحيح) [حم م] عن أبي هريرة. مختصر مسلم ١٩٢٢، الصحيحة ١٩٥٠."],[7686,"٢٤٠٤ - «والذي نفسي بيده لولا أن رجالا من المؤمنين لا تطيب أنفسهم أن يتخلفوا عني ولا أجد ما أحملهم عليه ما تخلفت عن سرية تغزوفي سبيل الله والذي نفسي بيده لوددت أني أقتل في سبيل الله ثم أحيا ثم أقتل ثم أحيا ثم أقتل ثم أحيا ثم أقتل» .\n(صحيح) [حم ق ن] عن أبي هريرة."],[7687,"٢٤٠٥ - «والذي نفسي بيده ليأتين على الناس زمان لا يدري القاتل في أي شيء قتل ولا يدري المقتول في أي شيء قتل» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ٢٠١٠."],[7688,"٢٤٠٦ - «والذي نفسي بيده ليوشكن أن ينزل فيكم ابن مريم حكما مقسطا وإماما عدلا فيكسر الصليب ويقتل الخنزير ويضع الجزية ويفيض المال حتى لا يقبله أحد وحتى تكون السجدة الواحدة خيرا من الدنيا وما فيها» .\n(صحيح) [حم ق ت هـ] عن أبي هريرة. الصحيحة ٢٤٥٧."],[7689,"٢٤٠٧ - «والذي نفسي بيده ليهلن ابن مريم بفج الروحاء حاجا أو معتمرا أو ليثنينهما» .\n(صحيح) [حم م] عن أبي هريرة. مختصر مسلم ٦٦٣، الصحيحة ٢٤٥٧."],[7690,"٢٤٠٨ - «والذي نفسي بيده ما أنزل في التوراة ولا في الإنجيل ولا في الزبور ولا في الفرقان مثلها - يعني أم القرآن - وإنها لسبع من المثاني والقرآن العظيم الذي أعطيته» ... [حم ت] عن أبي هريرة.\n(صحيح) صحيح أبي داود ١٣١٠، المشكاة ٢١٤٢، الترغيب ٢/٢١٦: حب، ك."],[7691,"٢٤٠٩ - «والذي نفسي بيده ما من رجل يدعوامرأته إلى فراشه فتأبى عليه إلا كان الذي في السماء ساخطا عليها حتى يرضى عنها» .\n(صحيح) [م] عن أبي هريرة."],[7692,"٢٤١٠ - «والذي نفسي بيده لا تدخلون الجنة حتى تؤمنوا ولا تؤمنوا حتى تحابوا أولا أدلكم على شيء إذا فعلتموه تحاببتم؟ أفشوا السلام بينكم» .\n(صحيح) [حم م د ت هـ] عن أبي هريرة. الإرواء ٧٧٧."],[7693,"٢٤١١ - «والذي نفسي بيده لا تذهب الدنيا حتى يمر الرجل على القبر فيتمرغ عليه ويقول: يا ليتني كنت مكان صاحب هذا القبر وليس به الدين إلا البلاء» .\n(صحيح) [م هـ] عن أبي هريرة. مختصر مسلم ٢٠٠٨."],[7694,"٢٤١٢ - \"والذي نفسي بيده لا تقوم الساعة حتى تكلم السباع الإنس وحتى يكلم الرجل عذبة سوطه وشراك نعله ويخبره فخذه بما يحدث أهله بعده\".\n(صحيح) [حم ت حب ك] عن أبي سعيد. الصحيحة ١٢٢."],[7695,"٢٤١٣ - «والذي نفسي بيده لا يؤمن أحدكم حتى أكون أحب إليه من والده وولده» .\n(صحيح) [حم خ ن] عن أبي هريرة."],[7696,"٢٤١٤ - «والذي نفسي بيده لا يؤمن عبد حتى يحب لأخيه ما يحب لنفسه من الخير» .\n(صحيح) [حم ن] عن أنس. الصحيحة ٧٣: أبو عوانة."],[7697,"٢٤١٥ - «والذي نفسي بيده لا يؤمن عبد حتى يحب لجاره ما يحب لنفسه» .\n(صحيح) [م] عن أنس. مختصر مسلم ٢٤، الصحيحة ٧٣: الطيالسي، حم، خ، ن، ت، الدارمي، هـ."],[7698,"٢٤١٦ - «[*» ... يا أيها الناس من آذى عمي فقد آذاني فإنما عم الرجل صنو أبيه] .\n(صحيح) [حم ت ك] عن عبد المطلب بن ربيعة [ك] عن العباس\". المشكاة ٦١٤٧."],[7699,"٢٤١٧ - «والذي نفسي بيده لا يكلم أحد في سبيل الله والله أعلم بمن يكلم في سبيله إلا جاء يوم القيامة وجرحه يشخب اللون لون الدم والريح ريح المسك» .\n(صحيح) [حم ق] عن أبي هريرة."],[7700,"٢٤١٨ - «والله إنك لخير أرض الله وأحب أرض الله إلي ولولا أني أخرجت منك ما خرجت» .\n(صحيح) [حم ت هـ حب ك] عن عبد الله بن عدي بن الحمراء. المشكاة ٢٧٢٥."],[7701,"(*) أو له [والذي نفسي بيده لا يدخل قلب رجل الإيمان حتى يحبكم لله ورسوله. ...] وقد ضعف شيخنا الألباني هذا القسم من الحديث، انظر ضعيف الجامع ٦١٢٥. - زهير."],[7702,"٢٤١٩ - «والله إني لأرجوأن أكون أخشاكم لله وأعلمكم بما أتقي» .\n(صحيح) [م د] عن عائشة. مختصر مسلم ٥٨٦."],[7703,"«والله إني لأستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرة» .\n(صحيح) [خ] عن أبي هريرة."],[7704,"٢٤٢٠ - «والله إني لأسمع بكاء الصبي وأنا في الصلاة فأخفف مخافة أن تفتن أمه» .\n(صحيح) [ت] عن أنس. خ: أذان."],[7705,"٢٤٢١ - «والله لأن يلج أحدكم بيمينه في أهله آثم له عند الله من أن يعطي كفارته التي افترض الله عليه» .\n(صحيح) [حم ق] عن أبي هريرة. مختصر مسلم ١٠٢٠، الإرواء ٢٠٨٤."],[7706,"«والله لأن يهدى بهداك واحد خير لك من حمر النعم» .\n(صحيح) [د] عن سهل بن سعد. فقه السيرة ٣٧١: ق١."],[7707,"«والله لا يلقي الله حبيبه في النار» .\n(صحيح) [ك] عن أنس. الصحيحة ٢٤٠٧: حم."],[7708,"٢٤٢٢ - «والله للدنيا أهون على الله من هذا عليكم» .\n(صحيح) [حم م د] عن جابر."],[7709,"٢٤٢٣ - \"والله لله أشد فرحا بتوبة عبده من رجل كان في سفر في فلاة من الأرض فأوى إلى ظل شجرة فنام تحتها واستيقظ فلم يجد راحلته فأتى شرفا فصعد عليه فلم ير شيئا ثم أتى آخر فأشرف فلم ير شيئا فقال: أرجع إلى مكاني الذي كنت فيه فأكون فيه حتى أموت فذهب فإذ براحلته تجر خطامها فالله أشد فرحا بتوبة عبده من هذا براحلته\".\n(صحيح) [حم م] عن النعمان بن بشير."],[7710,"(١) قلت: ومضى لفظهما برقم ١٥١١."],[7711,"٢٤٢٤ - «والله ليبعثنه الله يوم القيامة - يعني الحجر - له عينان يبصر بهما ولسان ينطق به يشهد على من استلمه بحق» .\n(صحيح) [ت] عن ابن عباس. المشكاة ٢٥٧٨، الترغيب ٢/١٢٢، ابن خزيمة، حب."],[7712,"٢٤٢٥ - «والله لينزلن ابن مريم حكما عادلا فليكسرن الصليب وليقتلن الخنزير وليضعن الجزية ولتتركن القلاص فلا يسعى عليها ولتذهبن الشحناء والتباغض والتحاسد وليدعون إلى المال فلا يقبله أحد» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ٢٠٥٩، الصحيحة ٢٤٥٧: حم، الآجري، ابن منده."],[7713,"«والله ما الدنيا في الآخرة إلا مثل ما يجعل أحدكم أصبعه هذه في اليم فلينظر بم يرجع» .\n(صحيح) [حم م هـ] عن المستورد."],[7714,"«والله لا تجدون بعدي أعدل عليكم مني» .\n(صحيح) [طب ك] عن أبي برزة١ ... [حم] عن أبي سعيد. الصحيحة ٢٤٠٦: الطيالسي، حم، ن - أبي برزة."],[7715,"٢٤٢٦ - «والله لا يؤمن والله لا يؤمن والله لا يؤمن الذي لا يأمن جاره بوائقه» .\n(صحيح) [حم خ] عن أبي شريح. حم ٤/٣١ و٦/٣٨٥، خ ٤/١١٨. حم ٢/٢٨٨و٣٣٦، ك ١/١٠و٤/١٦٥ - أبي هريرة."],[7716,"(١) الأصل أبو هريرة، وهو خطأ."],[7717,"٢٤٢٧ - «وأيم الله لا أقبل بعد يومي هذا من أحد هدية إلا أن يكون مهاجرا قرشيا أو أنصاريا أو دوسيا أو ثقفيا» .\n(صحيح) [د] عن أبي هريرة. الصحيحة ١٦٨٤١."],[7718,"«وأي داء أدوى من البخل؟» .\n(صحيح) [حم ق٢] عن جابر [ك] عن أبي هريرة. الروض النضير ٨٤٨: خد، طس، خط - جابر. طس، الخرائطي - كعب بن مالك. طب، طس - ابن عباس."],[7719,"«وجب الخروج على كل ذات نطاق في العيدين» .\n(صحيح) [حم] عن عمرة بنت رواحة. الصحيحة ٢٤٠٨: الطيالسي، حل، هق، خط."],[7720,"٢٤٢٨ - «وجبت أنتم شهداء في الأرض» .\n(صحيح) [ت هـ حب] عن أنس [حم هـ حب] عن أبي هريرة. أحكام الجنائز ص ٤٤ - ٤٥: حم، ق، ن، ك - أنس الطيالسي، د، ن - أبي هريرة."],[7721,"٢٤٢٩ - «وجبت صدقتك ورجعت إليك حديقتك» .\n(صحيح) [حم هـ] عن ابن عمرو. الصحيحة ٢٤٠٩: م، هـ - بريدة."],[7722,"«وددت أني لقيت إخواني الذين آمنوا ولم يروني» .\n(صحيح) [حم] عن أنس. صحيح الترغيب ١/٩٣: مالك، حم، م، ن، هـ - أبي هريرة."],[7723,"«وصب المؤمن كفارة لخطاياه» .\n(صحيح) [ك هب] عن أبي هريرة. الصحيحة ٢٤١٠: ابن أبي الدنيا."],[7724,"«وضع عن أمتي الخطأ والنسيان وما استكرهوا عليه» .\n(صحيح) [هق] عن ابن عمر. الإرواء ٨٢."],[7725,"(١) سبق تخريجه بلفظ: [لقد هممت.. ...] رقم ٥١٤٦.٢ كذا الأصل، وكذلك هو في بعض نسخ [الجامع الصغير]، منها نسخة [فيض القدير] خلافا للفيض نفسه، ووقع في [الجامع الكبير] ٢/٣٢٦ نحوه: [خ م] بعد [حم] وكل ذلك وهم، فإن الحديث لم يخرجاه، نعم رواه [خ] في موضعين من رواية جابر عن أبي بكر موقوفا عليه، وكذلك رواه أحمد ٣/٣٠٧ فكان حقه أن يبين أنه موقوف عندهما، وكذلك أخرجه أبو يعلى في [مسنده] ٢/٥٤٤."],[7726,"٢٤٣٠ - «وعدني ربي أن يدخل الجنة من أمتي سبعين ألفا بلا حساب عليهم ولا عذاب مع كل ألف سبعون ألفا وثلاث حثيات من حثيات ربي» .\n(صحيح) [حم ت حب] عن أبي أمامة. المشكاة ٥٥٥٦، السنة ٧٨٨، ٧٨٩: ابن أبي عاصم."],[7727,"«وفد الله ثلاثة: الغازي والحاج والمعتمر» .\n(صحيح) [ن حب ك] عن أبي هريرة. المشكاة ١٥٣٧، الترغيب ٢/١٦٥: ابن خزيمة، حل."],[7728,"«وفروا اللحى وخذوا من الشوارب» .\n(صحيح) [طس] عن أبي هريرة. الضعيفة ٤٧٤٩."],[7729,"«وفروا عثانينكم وقصوا سبالكم» .\n(حسن) [هب] عن أمامة. الصحيحة ١٢٤٥: حم."],[7730,"٢٤٣١ - «وقت صلاة الظهر إذا زالت الشمس وكان ظل الرجل كطوله ما لم يحضر العصر ووقت صلاة العصر ما لم تصفر الشمس ووقت صلاة المغرب ما لم يغب الشفق ووقت صلاة العشاء إلى نصف الليل الأوسط ووقت صلاة الصبح من طلوع الفجر ما لم تطلع الشمس فإذا طلعت الشمس فأمسك عن الصلاة فإنها تطلع بين قرني الشيطان» .\n(صحيح) [حم م د ن] عن ابن عمرو. صحيح أبي داود ٤٢٤."],[7731,"٢٤٣٢ - «وقيت شركم ووقيتم شرها» .\n(صحيح) [ق ن] عن ابن مسعود."],[7732,"٢٤٣٣ - «وكاء السه العينان فمن نام فليتوضأ» .\n(صحيح) [د] عن علي. صحيح أبي داود ١٩٨."],[7733,"«ولد آدم كلهم تحت لوائي يوم القيامة وأنا أول من يفتح له باب الجنة» .\n(صحيح) [ابن عساكر] عن حذيفة. الصحيحة ٢٤١١: لوين."],[7734,"«ولد الرجل من كسبه من أطيب كسبه فكلوا من أموالهم» .\n(صحيح) [د ك] عن عائشة. الإرواء ٨٣٨، الصحيحة ٢٤١٤."],[7735,"«ولد الزنا شر الثلاثة» .\n(صحيح) [حم د ك هق] عن أبي هريرة. الصحيحة ٦٧١."],[7736,"«ولد لي الليلة غلام فسميته باسم أبي إبراهيم» .\n(صحيح) [حم ق د] عن أنس."],[7737,"٢٤٣٤ - «ولم يفعل ذلك أحدكم؟ فإنه ليست نفس مخلوقة إلا الله خالقها» .\n(صحيح) [م د] عن أبي سعيد."],[7738,"٢٤٣٥ - «وما أنا والدنيا وما أنا والرقم» ١.\n(صحيح) [د] عن ابن عمر. الصحيحة ٢٤١٢: حم."],[7739,"٢٤٣٦ - «وما تعدون الشهادة إلا من قتل في سبيل الله؟ إن شهداءكم إذا لقليل القتل في سبيل الله شهادة والبطن شهادة والحرق شهادة والغرق شهادة والمغموم - يعني الهدم - شهادة والمجنوب شهادة والمرأة تموت بجمع» .\n(صحيح) [ن] عن عبد الله بن جبر٢. أحام الجنائز ٣٩ - ٤٠."],[7740,"٢٤٣٧ - «وما يدريك أنها رقية؟ قد أصبتم اقسموا واضربوا لي معكم سهما» .\n(صحيح) [حم ق ٤] عن أبي سعيد. مختصر مسلم ١٤٤٩، الإرواء ١٥٥٦."],[7741,"(١) الأصل الرحم، وهو خطأ، وصححته من الزيادة وغيره، فقد سبق الحديث بلفظ: [ما أنا] بإسقاط الواو، والصواب إثباتها، والخطأ المشار إليه هنا وقع هناك أيضا، ولكن صححته دون التنبيه عليه. رقم ٥٥٥٥.٢ الأصل جبير، وكذا في الزيادة، والصواب ما أثبتنا، ثم هو مجهول، ولم تثبت صحبته، والصواب في الحديث أنه من مسند جابر بن عتيك كما في [التهذيب] وهو رواية النسائي في [الصغرى] ."],[7742,"٢٤٣٨ - «وما يدريك؟ لعل الله قد اطلع على أهل بدر فقال: اعملوا ما شئتم فقد غفرت لكم» .\n(صحيح) [حم ق د ت] عن علي [د] عن أبي هريرة [حم] عن ابن عباس وعن جابر."],[7743,"٢٤٣٩ - «وهل ترك لنا عقيل من رباع» .\n(صحيح) [حم ق د ن هـ] عن أسامة بن زيد. مختصر مسلم ٦٩٢."],[7744,"٢٤٤٠ - «وهل تلد الإبل إلا النوق» .\n(صحيح) [حم د ت] عن أنس. المشكاة ٤٨٨٦."],[7745,"«ويح عمار تقتله الفئة الباغية يدعوهم إلى الجنة ويدعونه إلى النار» .\n(صحيح) [حم خ] عن أبي سعيد. الروض ٦٦٢، الصحيحة ٧١٠."],[7746,"٢٤٤١ - «ويحك! إن شأن الهجرة لشديد فهل لك من إبل تؤدي صدقتها؟ فاعمل من وراء البحار فإن الله لن يترك من عملك شيئا» .\n(صحيح) [حم ق د ن] عن أبي سعيد. مختصر مسلم ١١٨٧."],[7747,"٢٤٤٢ - «ويحكم! لا ترجعوا بعدي كفارا يضرب بعضكم رقاب بعض» .\n(صحيح) [ق] عن ابن عمر. مختصر مسلم ٤٨."],[7748,"«ويل للأعقاب من النار» .\n(صحيح) [ق د ن هـ] عن ابن عمرو [حم ق ت هـ] عن أبي هريرة. صحيح أبي داود ٨٧."],[7749,"«ويل للأعقاب وبطون الأقدام من النار» .\n(صحيح) [حم ك] عن عبد الله بن الحارث. صحيح الترغيب ١/٢٦٨، الروض النضير ١٣٠."],[7750,"٢٤٤٣ - «ويل للعراقيب من النار» .\n(صحيح) [م] عن أبي هريرة [حم ق] عن عائشة [هـ] عن جابر."],[7751,"«ويل للعرب من شر قد اقترب أفلح من كف يده» .\n(صحيح) [د ك] عن أبي هريرة. المشكاة ٥٤٠٤١."],[7752,"«ويل للذي يحدث فيكذب ليضحك به القوم ويل له ويل له» .\n(حسن) [حم د ت ك] عن معاوية بن حيدة. المشكاة ٤٨٣٨."],[7753,"«ويل للمكثرين إلا من قال بالمال هكذا وهكذا» .\n(صحيح) [هـ] عن أبي سعيد. الصحيحة ٣٣٩: حب."],[7754,"«ويل للنساء من الأحمرين: الذهب والمعصفر» .\n(حسن) [هب] عن أبي هريرة. الصحيحة ٣٣٩: حب."],[7755,"٢٤٤٤ - «ويلك! أو لست أحق أهل الأرض أن يتقي الله؟» .\n(صحيح) [ق] عن أبي سعيد. السنة ٩٢٣."],[7756,"٢٤٤٥ - «ويلك! قطعت عنق صاحبك من كان منكم مادحا أخاه لا محالة فليقل: أحسب فلانا والله حسيبه ولا أزكي على الله أحدا أحسبه كذا وكذا إن كان يعلم ذلك منه» .\n(صحيح) [حم ق د هـ] عن أبي بكرة. مختصر مسلم ١٥١٠."],[7757,"٢٦٤٦ - «ويلك! ومن يعدل إذا لم أعدل! قد خبت وخسرت إن لم أكن أعدل» .\n(صحيح) [ق] عن أبي سعيد. السنة: حم، د، ن، ابن أبي عاصم."],[7758,"(١) ومنه يتبين أن الشطر الثاني من الحديث ليس عند [ك]، وأن الشطر الأول متفق عليه!!."],[7759,"فصل في المحلى بـ\"ال\" من هذا الحرف."],[7760,"«الوائدة والموءودة في النار» .\n(صحيح) [د] عن ابن مسعود. المشكاة ١٢: حب، طب - الهيثم بن كليب."],[7761,"٢٤٤٧ - «الوائدة والموءودة في النار إلا أن تدرك الوائدة الإسلام فتسلم» .\n(صحيح) [حم ن] عن سلمة بن يزيد الجعفي. المصدر نفسه."],[7762,"«الواحد شيطان والاثنان شيطانان والثلاثة ركب» .\n(صحيح) [ك] عن أبي هريرة. الصحيحة ٦٢."],[7763,"«الوالد أوسط أبواب الجنة» .\n(صحيح) [حم ت هـ ك] عن أبي الدرداء. الصحيحة ٩١٠، المشكاة ٤٩٢٨."],[7764,"«الوتر بليل» .\n(صحيح) [حم ع] عن أبي سعيد. الصحيحة ٢٤١٣."],[7765,"٢٤٤٨ - «الوتر حق على كل مسلم فمن شاء أوتر بسبع ومن شاء أوتر بخمس ومن شاء بثلاث ومن شاء أوتر بواحدة فمن غلب فليومئ إيماء» .\n(صحيح) [د ن هـ حب ك] عن أبي أيوب. صحيح أبي داود ١٢٧٨: الدارمي، الطحاوي، ابن نصر."],[7766,"«الوتر ركعة من آخر الليل» .\n(صحيح) [م د ن] عن ابن عمر [حم طب] عن ابن عباس. الإرواء ٤١٨."],[7767,"«الوزغ فويسق» .\n(صحيح) [ن حب] عن عائشة. حم ٦/٨٧و ٢٧١و ٢٧٩ خ: حج، م: سلام، هـ: صيد."],[7768,"«الوزن وزن أهل مكة والمكيال مكيال أهل المدينة» .\n(صحيح) [د ن] عن ابن عمر. الصحيحة ١٦٥، الإرواء ١٣٤٢."],[7769,"«الوسيلة درجة عند الله ليس فوقها درجة فسلوا الله أن يؤتيني الوسيلة» .\n(صحيح) [حم] عن أبي سعيد. م ٢/٤ عبد الله بن عمرو١."],[7770,"«الوضوء شطر الإيمان،.. ...» .\n(صحيح) [ش] عن حسان بن عطية مرسلا. الضعيفة ٤٧٦٢."],[7771,"٢٤٤٩ - «الوضوء مما أنضجت النار» .\n(صحيح) [د] عن أبي هريرة. صحيح أبي داود ١٨٨."],[7772,"«الوضوء مما مست النار» .\n(صحيح) [م] عن زيد بن ثابت."],[7773,"«الوضوء مما مست النار ولو من ثور أقط» .\n(حسن) [ت] عن أبي هريرة. صحيح أبي داود ١٨٨."],[7774,"«الوضوء يكفر ما قبله ثم تصير الصلاة نافلة» .\n(حسن) [حم] عن أبي أمامة. صحيح الترغيب ١٨٢."],[7775,"«الولاء لحمة كلحمة النسب لا يباع ولا يوهب» .\n(صحيح) [طب] عن عبد الله ابن أبي أوفى ... [ك هق] عن ابن عمر. الإرواء ١٦٦٨، أحاديث البيوع."],[7776,"(١) قلت: ومضى لفظه برقم ٦١٣."],[7777,"«الولاء لمن أعتق» .\n(صحيح) [حم طب] عن ابن عباس. الإرواء ١٣٠٨، الروض ٧٨٩: مالك، حم، ق، د، ن، هـ، الطحاوي، ابن الجارود، قط. هق - عائشة."],[7778,"«الولاء لمن أعطى الورق١ وولي النعمة» .\n(صحيح) [ق ٣] عن عائشة. الروض النضير ٧٨٩، الإرواء ١٣٠٨."],[7779,"«الولد ثمرة القلب وإنه مجبنة ومبخلة محزنة» .\n(صحيح) [ع] عن أبي سعيد. الضعيفة ٤٧٦٤."],[7780,"«الولد للفراش وللعاهر الحجر» .\n(صحيح) [ق د ن هـ] عن عائشة [حم ق ت ن هـ] عن أبي هريرة [د] عن عثمان [ن] عن ابن مسعود وابن الزبير [هـ] عن عمر وأبي أمامة. مختصر مسلم ٨٧٢، الإرواء ٢١٠٨."],[7781,"«الولد من كسب الوالد» .\n(صحيح) [طس] عن ابن عمر. الصحيحة ٢٤١٤، الإرواء ٨٣٨."],[7782,"(١) الورق: الفضة."],[7783,"حرف اللام ألف."],[7784,"«لا آكل وأنا متكئ» .\n(صحيح) [حم خ د هـ] عن أبي جحيفة."],[7785,"«لا أجر لمن لا حسبة له» .\n(حسن) [ابن المبارك] عن القاسم مرسلا. الصحيحة ٢٤١٥ الديلمي - أبي ذر."],[7786,"٢٤٥٠ - «لا أحد أغير من الله ولذلك حرم الفواحش ما ظهر منها وما بطن ولا أحد أحب إليه المدح من الله ولذلك مدح نفسه ولا أحد أحب إليه العذر من الله من أجل ذلك أنزل الكتاب وأرسل الرسل» .\n(صحيح) [حم ق ت] عن ابن مسعود."],[7787,"«لا إخصاء في الإسلام» [*] .\n(صحيح) [هق] عن ابن عباس. غاية المرام ٤٨٢."],[7788,"٢٤٥١ - «لا أركب الأرجوان ولا ألبس المعصفر ولا ألبس القميص المكفف بالحرير ألا وطيب الرجال ريح لا لون له ألا وطيب النساء لون لا ريح له» .\n(صحيح) [حم د ك] عن عمران بن حصين. المشكاة ٤٣٥٤."],[7789,"«لا إسعاد في الإسلام ولا عقر ولا شغار في الإسلام ولا جلب في الإسلام ولا جنب ومن انتهب فليس منا» .\n(صحيح) [حم ن حب] عن أنس. المشكاة ٢٩٤٧."],[7790,"(*) وله تتمة ضعيفة انظر [ضعيف الجامع] ٦١٨٤، و[غاية المرام] ص ٢٨١. زهير."],[7791,"«لا إسلال ولا غلول» .\n(حسن) [طب] عن عمرو بن عوف. المشكاة ٤٠٤٦."],[7792,"٢٤٥٢ - «لا أعده كاذبا: الرجل يصلح بين الناس يقول القول لا يريد به إلا الإصلاح والرجل يقول في الحرب والرجل يحدث امرأته والمرأة تحدث زوجها» .\n(صحيح) [د] عن أم كلثوم بنت عقبة. الصحيحة ٥٤٥."],[7793,"٢٤٥٣ - «لا أعرفن ما مات منكم ميت ما كنت بين أظهركم إلا آذنتموني به فإن صلاتي عليه له رحمة» .\n(صحيح) [هـ] عن زيد بن ثابت. الإرواء ٨٢٧، الجنائز ٨٨٠."],[7794,"٢٤٥٤ - «لا ألفين أحدكم متكئا على أريكته يأتيه الأمر من أمري مما أمرت به أو نهيت عنه فيقول: لا أدري ما وجدنا في كتاب الله اتبعناه» .\n(صحيح) [حم د ت هـ حب ك] عن أبي رافع. المشكاة ١٦٢."],[7795,"٢٤٥٥ - \"لا ألفين أحدكم يجيء يوم القيامة على رقبته بعير له رغاء يقول: يا رسول الله أغثني فأقول: لا أملك لك شيئا قد أبلغتك ; لا ألفين أحدكم يجيء يوم القيامة على رقبته فرس له حمحمة فيقول: يا رسول الله أغثني فأقول: لا أملك لك شيئا قد أبلغتك ; لا ألفين أحدكم يجيء يوم القيامة على رقبته شاة لها ثغاء يقول: يا رسول الله أغثني فأقول: لا أملك لك شيئا قد أبلغتك ; لا ألفين أحدكم يجيء يوم القيامة على رقبته نفس لها صياح فيقول: يا رسول الله أغثني فأقول: لا أملك لك شيئا قد أبلغتك ; لا ألفين أحدكم يجيء يوم القيامة على رقبته رقاع تخفق فيقول: يا رسول الله أغثني فأقول: لا أملك لك شيئا قد أبلغتك ; لا ألفين أحدكم يجيء يوم القيامة على رقبته صامت فيقول: يا رسول الله أغثني فأقول: لا أملك لك شيئا قد أبلغتك\".\n(صحيح) [حم ق] عن أبي هريرة. مختصر مسلم ١٢١٣."],[7796,"٢٤٥٦ - «لا ألفين١ أقواما من أمتي يأتون يوم القيامة بحسنات أمثال جبال تهامة بيضاء فيجعلها الله هباء منثورا أما إنهم إخوانكم ومن جلدتكم ويأخذون من الليل كما تأخذون ولكنهم قوم إذا خلوا بمحارم الله انتهكوها» .\n(صحيح) [هـ] عن ثوبان. الترغيب ٣/١٧٨."],[7797,"٢٤٥٧ - «لا إله إلا الله إن للموت سكرات» .\n(صحيح) [حم خ] عن عائشة."],[7798,"٢٤٥٨ - «لا إله إلا الله ويل للعرب من شر قد اقترب فتح اليوم من ردم يأجوج مثل هذه - وحلق بإصبعيه الإبهام والتي تليها - قيل: أنهلك وفينا الصالحون؟ قال: نعم إذا كثر الخبث» .\n(صحيح) [ق ن هـ] عن زينب بنت جحش. مختصر مسلم ١٩٨٧، الصحيحة ٩٨٧."],[7799,"٢٤٥٩ - «لا أمس أيدي النساء» ٢.\n(صحيح) [طس] عن عقيلة بنت عبيد."],[7800,"٢٤٦٠ - «لا أيم الله لا تصاحبنا راحلة عليها لعنة» .\n(صحيح) [م] عن أبي بردة الإرواء ٢١٨٤."],[7801,"«لا إيمان لمن لا أمانة له ولا دين لمن لا عهد له» .\n(صحيح) [حم حب] عن أنس. إيمان ابن أبي شيبة ٧، المشكاة ٣٥، الروض ١/٥٢٦."],[7802,"«لا تأتوا الكهان» .\n(صحيح) [طب] عن معاوية بن الحكم. الإرواء ٣٨٩: م."],[7803,"(١) كذا في الأصل تبعا لأصله [الزيادة] وهو وهم، والصواب: [لأعلمن] كما سبق التنبيه عليه رقم ٥٠٢٨.٢ قلت: هو في معنى قوله صلى الله عليه وآله وسلم: [إني لا أصافح النساء]، وقد مضى برقم ٢٥١٣."],[7804,"«لا بأس بالحيوان واحد باثنين يدا بيد» .\n(صحيح) [حم هـ] عن جابر. الصحيحة ٢٤١٦."],[7805,"«لا بأس بالغنى لمن اتقى والصحة لمن اتقى خير من الغنى وطيب النفس من النعيم» .\n(صحيح) [حم هـ ك] عن يسار بن عبيد. الصحيحة ١٧٤."],[7806,"«لا بأس بالقمح بالشعير اثنين بواحد يدا بيد» .\n(صحيح) [طب] عن عبادة. أحاديث البيوع: د، ن الطحاوي. هق."],[7807,"٢٤٦١ - «لا بأس ولينصر الرجل أخاه ظالما أو مظلوما إن كان ظالما فلينهه فإنه له نصر وإن كان مظلوما فلينصره» .\n(صحيح) [م] عن جابر. مختصر مسلم ١٨٣٢."],[7808,"«لا بد من العريف والعريف في النار» .\n(حسن) [أبونعيم في المعرفة] عن جعونة بن زياد. الصحيحة ١٤١٧: د - رجل. أبو الشيخ، أبو نعيم - أنس."],[7809,"«لا بر أن يصام في السفر» .\n(صحيح) [طب] عن ابن عمرو. صحيح الترغيب ١٠٤٨."],[7810,"«لا تأتي مائة سنة وعلى الأرض نفس منفوسة اليوم» .\n(صحيح) [م] عن أبي سعيد."],[7811,"«لا تأذن امرأة في بيت زوجها إلا بإذنه.. ...» .\n(صحيح) [طب] عن ابن عباس. الضعيفة ٤٧٧١."],[7812,"«لا تؤذن حتى يستبين لك الفجر هكذا» .\n(حسن) [د] عن بلال. صحيح أبي داود ٥٤٥."],[7813,"٢٤٦٢ - «لا تأذنوا لمن لم يبدأ بالسلام» .\n(صحيح) [هب الضياء] عن جابر. الصحيحة ٨١٧."],[7814,"«لا تؤذوا مسلما بشتم كافر» .\n(صحيح) [ك هق] عن سعيد بن زيد. الترغيب ٤/١٧٥."],[7815,"٢٤٦٣ - «لا تؤذي امرأة زوجها في الدنيا إلا قالت زوجته من الحور العين: لا تؤذيه قاتلك الله فإنما هو عندك دخيل يوشك أن يفارقك إلينا» .\n(صحيح) [حم ت] عن معاذ. الصحيحة ١٧٣."],[7816,"«لا تأكلوا البصل.. ...» .\n(صحيح) [هـ] عن عقبة بن عامر. يشهد له الحديث المتقدم ٦٨٥٣و ٦٨٥٤."],[7817,"«لا تأكلوا بالشمال فإن الشيطان يأكل بالشمال» .\n(صحيح) [هـ] عن جابر. الصحيحة ١٢٣٦: حم، م، ابن عساكر."],[7818,"٢٤٦٤ - «لا تبادروا الإمام إذا كبر فكبروا وإذا قال» ولا الضالين: فقولوا: آمين وإذا ركع فاركعوا وإذا قال سمع الله لمن حمده فقولوا: اللهم ربنا ولك الحمد ولا ترفعوا قبله\".\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ٢٧٥."],[7819,"٢٤٦٥ - «لا تبادروني بركوع ولا بسجود فإنه مهما أسبقكم به إذا ركعت تدركوني إذا رفعت ومهما أسبقكم به إذا سجدت تدركوني به إذا رفعت إني قد بدنت» .\n(صحيح) [حم د هـ] عن معاوية. صحيح أبي داود ٦٣١، الإرواء ٥٠٩."],[7820,"«لا تباشر المرأة المرأة فتنعتها١ لزوجها كأنه ينظر إليها» .\n(حسن) [حم خ د ت] عن ابن مسعود."],[7821,"٢٤٦٦ - \"لا تباع الصبرة٢ من الطعام بالصبرة من الطعام ولا الصبرة من الطعام بالكيل المسمى من الطعام\".\n(صحيح) [ن] عن جابر. أحاديث البيوع."],[7822,"(١) أي تصفها، وهو رواية لأحمد ١/٣٨٠.٢ بالضم ما جمع من الطعام بلا كيل ووزن."],[7823,"«لا تباغضوا ولا تدابروا ولا تنافسوا وكونوا عباد الله إخوانا» .\n(صحيح) [م] عن أبي هريرة. غاية المرام ٤٠٤."],[7824,"٢٤٦٧ - «لا تباغضوا ولا تقاطعوا ولا تدابروا ولا تحاسدوا وكونوا عباد الله إخوانا كما أمركم الله ولا يحل لمسلم أن يهجر أخاه فوق ثلاثة أيام» .\n(صحيح) [حم ق د] عن أنس. غاية المرام ٤٠٤، مختصر مسلم ١٨٠٠."],[7825,"٢٤٦٨ - «لا تبتاعوا التمر حتى يبدو صلاحه ولا تبتاعوا التمر بالتمر» .\n(صحيح) [م] عن أبي هريرة [ق ن] عن ابن عمر. أحاديث البيوع."],[7826,"٢٤٦٩ - «لا تبتاعوا الثمرة حتى يبدو صلاحها وتذهب عنها الآفة» .\n(صحيح) [م] عن ابن عمر. أحادبث البوع."],[7827,"٢٤٧٠ - «لا تبتاعوا الذهب بالذهب إلا مثلا بمثل ولا زيادة بينهما ولا نظرة» .\n(صحيح) [هـ] عن عبادة بن الصامت. أحاديث البيوع."],[7828,"«لا تبدءوا اليهود ولا النصارى بالسلام وإذا لقيتم أحدهم في طريق فاضطروه إلى أضيقه» .\n(صحيح) [حم م د ت] عن أبي هريرة. مختصر ١٤٣٢، الصحيحة ٧٠٤، الإرواء ١٢٧١: خد، الطحاوي، هق."],[7829,"٢٤٧١ - «لا تبع طعاما حتى تشتريه وتستوفيه» .\n(صحيح) حم ن\" عن حكيم بن حزام. أحاديث البيوع."],[7830,"٢٤٧٢ - «لا تبع ما ليس عندك» .\n(صحيح) [حم ٤] عن حكيم بن حزام. المشكاة ٢٨٦٧."],[7831,"٢٤٧٣ - «لا تبقين في رقبة بعير قلادة من وتر إلا قطعت» .\n(صحيح) [ق د] عن أبي بشير."],[7832,"٢٤٧٤ - «لا تبكيه ما زالت الملائكة تحفه بأجنحتها حتى رفعتموه» .\n(صحيح) [ن] عن جابر. أحكام الجنائز ٢٠."],[7833,"٢٤٧٥ - «لا تبيعوا الدينار بالدينارين ولا الدرهم بالدرهمين» .\n(صحيح) [م] عن عثمان. مختصر مسلم ٩٥١."],[7834,"٢٤٧٦ - «لا تبيعوا الذهب بالذهب إلا سواء بسواء والفضة بالفضة إلا سواء بسواء وبيعوا الذهب بالفضة والفضة بالذهب كيف شئتم» .\n(صحيح) [خ] عن أبي بكرة. أحاديث البيوع: حم، م، ن."],[7835,"٢٤٧٧ - «لا تبيعوا الذهب بالذهب إلا مثلا بمثل ولا تشفوا بعضها على بعض ولا تبيعوا الورق بالورق إلا مثلا بمثل ولا تشفوا بعضها على بعض ولا تبيعوا منها غائبا بناجز» .\n(صحيح) [حم ق ت ن] عن أبي سعيد. أحاديث البيوع، الإرواء ١٣٣٩."],[7836,"٢٤٧٨ - «لا تبيعوا الذهب بالذهب إلا وزنا بوزن» .\n(صحيح) [م د] عن فضالة بن عبيد. أحاديث البيوع: حم، الطحاوي، هق."],[7837,"٢٤٧٩ - \"لا تبيعوا الذهب بالذهب ولا الورق بالورق، إلا وزنا بوزن مثلا بمثل سواء بسواء\".\n(صحيح) [حم م] عن أبي سعيد. أحاديث البيوع، الإرواء ١٣٣٩: الطيالسي، الطحاوي."],[7838,"«لا تتخذوا الضيعة فترغبوا في الدنيا» .\n(صحيح) [حم ت ك] عن ابن مسعود. الصحيحة ١٢."],[7839,"«لا تتخذوا المساجد طرقا إلا لذكر أو صلاة» .\n(حسن) [طب] عن ابن عمر. الصحيحة ١٠٠١."],[7840,"٢٤٨٠ - «لا تتخذوا بيوتكم قبورا» .\n(صحيح) [هـ] عن ابن عمر. أحكام الجنائز ٢١٢: حم، ق١."],[7841,"«لا تتخذوا بيوتكم قبورا صلوا فيها» .\n(صحيح) [حم] عن زيد بن خالد. الصحيحة ٢٤١٨: ابن نصر. حب - أبي هريرة."],[7842,"«لا تتخذوا شيئا فيه الروح غرضا» .\n(صحيح) [م ن هـ] عن ابن عباس. غاية المرام ٣٨٢، مختصر البخاري: خ، تخ."],[7843,"«لا تترك هذه الأمة شيئا من سنن الأولين حتى تأتيه» .\n(صحيح) [طس] عن المستورد. يشهد له الحديث المتقدم ٥٠٦٣."],[7844,"«لا تتركوا النار في بيوتكم حين تنامون» .\n(صحيح) [حم ق د ت هـ] عن ابن عمر."],[7845,"«لا تتمنوا الموت» .\n(صحيح) [هـ] عن خباب. حم ٥/١٠٩ - ١١٢، ق: الدعوات."],[7846,"«لا تتمنوا لقاء العدو وإذا لقيتموهم فاصبروا» .\n(صحيح) [ق] عن أبي هريرة."],[7847,"«لا تجادلوا في القرآن فإن جدالا فيه كفر» .\n(صحيح) [الطيالسي هب] عن ابن عمرو. الصحيحة ٢٤١٩."],[7848,"(١) مضى لفظهم برقم ١٥٢٠."],[7849,"٢٤٨١ - «لا تجزئ صلاة الرجل حتى يقيم ظهره في الركوع والسجود» .\n(صحيح) [د ت] عن أبي مسعود. المشكاة ٨٧٨، صحيح أبي داود ٨٠٦."],[7850,"«لا تجزئ صلاة لا يقيم الرجل فيها صلبه في الركوع والسجود» .\n(صحيح) [حم ن هـ] عن أبي مسعود. المصدران السابقان."],[7851,"٢٤٨٢ - «لا تجعلوا بيوتكم قبورا ولا تجعلوا قبري عيدا وصلوا علي فإن صلاتكم تبلغني حيث كنتم» .\n(صحيح) [د] عن أبي هريرة. تحذير الساجد ٩٦، فضل الصلاة ٢٠."],[7852,"٢٤٨٣ - «لا تجعلوا بيوتكم مقابر إن الشيطان ينفر من البيت الذي يقرأ فيه سورة البقرة» .\n(صحيح) [حم م ت] عن أبي هريرة. أحكام الجنائز ص ٢١٢."],[7853,"«لا تجلسوا بين رجلين إلا بإذنهما» .\n(حسن) [د] عن ابن عمر. المشكاة ٤٧٠٤."],[7854,"«لا تجلسوا على القبور ولا تصلوا إليها» .\n(صحيح) [حم م ٣] عن أبي مرثد. مختصر مسلم ٤٩٩، أحكام الجنائز ص ٢٠٩ - ٢١٠."],[7855,"٢٤٨٤ - «لا تجمعن كذبا وجوعا» .\n(حسن) [حم هـ] عن أسماء بنت عميس. آداب الزفاف ١٧."],[7856,"«لا تجمعوا بين اسمي وكنيتي» .\n(صحيح) [حم] عن [عم] ١ عبد الرحمن بن أبي عمرة. المشكاة ٤٧٦٩."],[7857,"(١) سقطت من [الجامع الصغير] والصواب إثباته كما وقع في [الكبير]، انظر التخريج المذكور أعلاه."],[7858,"٢٤٨٥ - «لا تجمعوا بين الرطب والبسر وبين الزبيب والتمر نبيذا» .\n(صحيح) [حم ق] عن جابر."],[7859,"«لا تجني أم على ولد» .\n(صحيح) [ن هـ] عن طارق المحاربي. الصحيحة ٩٨٩: الإرواء ٢٣٠٣."],[7860,"«لا تجني نفس على أخرى» .\n(صحيح) [ن هـ] عن أسامة بن شريك. الإرواء ٢٣٠٣، الصحيحة ٩٨٨."],[7861,"«لا تجوز شهادة بدوي على صاحب قرية» .\n(صحيح) [د هـ ك] عن أبي هريرة. الإرواء ٢٦٧٤، المشكاة ٣٧٨٣."],[7862,"٢٤٨٦ - «لا تجوز شهادة خائن ولا خائنة ولا زان ولا زانية ولا ذي غمر على أخيه في الإسلام» .\n(حسن) [د هـ] عن ابن عمرو. الإرواء ٢٦٦٩، المشكاة ٣٣٨٢."],[7863,"«لا تجوز شهادة ذي الظنة ولا ذي الحنة» .\n(حسن) [ك هق] عن أبي هريرة. الإرواء ٢٦٧٤."],[7864,"٢٤٨٧ - «لا تجوز لامرأة هبة في مالها إلا بإذن زوجها إذا ملك زوجها عصمتها» .\n(صحيح) [حم ن هـ] عن ابن عمرو [هـ] عن كعب بن مالك. صحيح الترغيب ٩٣٢: حم - عبادة. حم - مجاهد مرسلا."],[7865,"«لا تحدوا النظر إلى المجذومين» .\n(صحيح) [الطيالسي هق] عن ابن عباس. الصحيحة ١٠٦٤."],[7866,"٢٤٨٨ - «لا تحرم الإملاجة ولا الإملاجتان» .\n(صحيح) [حم م ن هـ] عن أم الفضل. الإرواء ٢١٤٩، مختصر مسلم ٨٧٨."],[7867,"«لا تحرم المصة ولا المصتان» .\n(صحيح) [حم م ٤] عن عائشة [ن حب] عن الزبير. الإرواء ٢١٤٨."],[7868,"٢٤٨٩ - «لا تحاسدوا ولا تناجشوا ولا تباغضوا ولا تدابروا ولا يبع بعضكم على بيع بعض وكونوا عباد الله إخوانا المسلم أخوالمسلم ولا يخذله ولا يحقره التقوى هاهنا - وأشار إلى صدره - بحسب امرئ من الشر أن يحقر أخاه المسلم كل المسلم على المسلم حرام دمه وماله وعرضه» .\n(صحيح) [حم م] عن أبي هريرة. الإرواء ٢٤٥٠: ت١."],[7869,"٢٤٩٠ - «لا تحروا بصلاتكم طلوع الشمس ولا غروبها فإنها تطلع بقرني شيطان» .\n(صحيح) [ق] عن ابن عمر [ن] عن عائشة. مختصر مسلم ٢١٠، الإرواء ٤٧٩."],[7870,"«لا تحسبن أنا ذبحنا الشاة من أجلك لنا غنم مائة لا نريد أن نزيد عليها فإذا ولد الراعي بهمة ذبحنا مكانها شاة» .\n(صحيح) [د حب] عن لقيط بن صبرة. صحيح أبي داود ١٣٠و ١٣١: حم."],[7871,"٢٤٩١ - «لا تحقرن من المعروف شيئا ولو أن تلقى أخاك بوجه طلق» .\n(صحيح) [حم م ت] عن أبي ذر. مختصر ١٧٨٢."],[7872,"٢٤٩٢ - «لا تحلفوا بآبائكم» .\n(صحيح) [خ ن] عن ابن عمر. مختصر مسلم ١٠١١."],[7873,"٢٤٩٣ - «لا تحلفوا بآبائكم من حلف بالله فليصدق ومن حلف له بالله فليرض ومن لم يرض بالله فليس من الله» .\n(صحيح) [هـ] عن ابن عمر. الإرواء ٢٦٩٨."],[7874,"(١) ومضى لفظه في: [المسلم أخو المسلم.. ...] ٦٧٠٦."],[7875,"«لا تحلفوا بآبائكم ولا بالطواغيت» .\n(صحيح) [حم ن هـ] عن عبد الرحمن بن سمرة. مختصر ١٠١٢."],[7876,"٢٤٩٥ - «لا تحلفوا بآبائكم ولا بأمهاتكم ولا بالأنداد ولا تحلفوا إلا بالله ولا تحلفوا إلا وأنتم صادقون» .\n(صحيح) [د ن] عن أبي هريرة. المشكاة ٣٤١٨، الإرواء ٢٦٩٨."],[7877,"٢٤٩٦ - «لا تحل الصدقة لغني إلا لخمسة: لغاز في سبيل الله أو لعامل عليها أو لغارم أو لرجل اشتراها بماله أو لرجل كان له جار مسكين فتصدق على المسكين فأهداها المسكين للغني» .\n(صحيح) [حم د هـ ك] عن أبي سعيد. الإرواء ٨٧٠: ابن خزيمة، ابن الجارود، هق. مالك - عطاء بن يسار مرسلا."],[7878,"٢٤٩٧ - «لا تحل الصدقة لغني ولا لذي مرة سوي» .\n(صحيح) [حم د ت ك] عن ابن عمر [حم ن هـ] عن أبي هريرة. الإرواء ٨٧٧."],[7879,"٢٤٩٨ - «لا تحل النهبى ولا كل ذي ناب من السباع ولا تحل المجثمة» .\n(صحيح) [حم ن] عن أبي ثعلبة. الصحيحة ٢٣٩١: الدارمي، هق، حم - أبي الدرداء."],[7880,"٢٤٩٩ - «لا تحل للأول حتى يجامعها الآخر» .\n(صحيح) [ن] عن ابن عمر. الإرواء ١٨٨٧."],[7881,"٢٥٠٠ - «لا تختصوا ليلة الجمعة بقيام من بين الليالي ولا تختصوا يوم الجمعة بصيام من بين الأيام إلا أن يكون في صوم يصومه أحدكم» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ٦٢٦، الصحسحة ٩٨٠: ابن سعد - ابن سيرين مرسلا."],[7882,"٢٥٠١ - \"لا تختلفوا فإن من كان قبلكم اختلفوا، فهلكوا\".\n(صحيح) [خ] عن ابن مسعود."],[7883,"٢٥٠٢ - «لا تختلفوا فتختلف قلوبكم» .\n(صحيح) [حم د] عن البراء. صحيح أبي داود ٦٧٠."],[7884,"٢٥٠٣ - «لا تخيروا بين الأنبياء فإن الناس يصعقون يوم القيامة فأكون أول من تنشق عنه الأرض فإذا موسى آخذ بقائمة من قوائم العرش فلا أدري كان فيمن صعق أم حوسب بصعقته الأولى؟» .\n(صحيح) [حم ق] عن أبي سعيد. شرح الطحاوية ١٢٨و ٥٥٣/١، مختصر العلو ٦١."],[7885,"٢٥٠٤ - «لا تخيروني على موسى فإن الناس يصعقون يوم القيامة فأصعق معهم فأكون أول من يفيق فإذا موسى باطش بجانب العرش فلا أدري أكان فيمن صعق فأفاق قبلي أو كان ممن استثنى الله؟» .\n(صحيح) [حم ق د هـ] عن أبي هريرة. شرح الطحاوية ١٢٦."],[7886,"«لا تخيفوا أنفسكم بالدين» .\n(حسن) [هق] عن عقبة بن عامر. الصحيحة ٢٤٢٠: حم، خد، ع، طب."],[7887,"٢٥٠٥ - «لا تدخل الملائكة بيتا فيه تماثيل أو تصاوير» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ١٣٦٤."],[7888,"٢٥٠٦ - «لا تدخل الملائكة بيتا فيه صورة إلا رقم في ثوب» .\n(صحيح) [حم ق د ن] عن أبي طلحة. غاية المرام ١١٨و ١٣٥."],[7889,"«لا تدخل الملائكة بيتا فيه كلب ولا صورة» .\n(صحيح) [حم ق ت ن هـ] عن أبي طلحة. غاية المرام ١١٨و ١٣٥."],[7890,"٢٥٠٧ - «لا تدخلوا على هؤلاء المعذبين إلا أن تكونوا باكين فإن لم تكونوا باكين فلا تدخلوا عليهم لا يصيبكم ما أصابهم» .\n(صحيح) [حم ق] عن ابن عمر. فقه السيرة ٤٤١، الصحيحة ١٩."],[7891,"٢٥٠٨ - «لا تدع تمثالا إلا طمسته ولا قبرا مشرفا إلا سويته» .\n(صحيح) [م ن] عن علي. مختصر مسلم ٤٨٨، أحكام الجنائز ٢٠٧: الطيالسي، حم، د، ت، طص، ك، هق."],[7892,"٢٥٠٩ - «لا تدعوا بالموت ولا تتمنوه فمن كان داعيا لا بد فليقل: اللهم أحيني ما كانت الحياة خيرا لي وتوفني إذا كانت الوفاة خيرا لي» .\n(صحيح) [ن] عن أنس. أحكام الجنائز ٤:ق، هق١."],[7893,"٢٥١٠ - «لا تدعوا على أنفسكم إلا بخير فإن الملائكة يؤمنون على ما تقولون» .\n(صحيح) [حم م د] عن أم سلمة. أحكام الجنائز ١٢: هق."],[7894,"٢٥١١ - «لا تدعوا على أنفسكم ولا تدعوا على أولادكم ولا تدعوا على خدمكم ولا تدعوا على أموالكم لا توافقوا من الله ساعة يسأل٢ فيها عطاء فيستجاب لكم» .\n(صحيح) [د] عن جابر. مختصر مسلم ١٥٣٧، حب ٢٤١١."],[7895,"«لا تدفنوا موتاكم بالليل إلا أن تضطروا» .\n(صحيح) [هـ] عن جابر. أحكام الجنائز ٥٨: حم، م، د، ابن الجارود."],[7896,"«لا تديموا النظر إلى المجذومين» .\n(صحيح) [حم هـ] عن ابن عباس. الصحيحة ١٠٦٤: تخ، ابن أبي شيبة، الضياء."],[7897,"«لا تذبحن ذات در» .\n(صحيح) [ت] عن أبي هريرة. الصحيحة ١٦٣١: ك. حم في [الزهد]- أبي سلمة."],[7898,"(١) قلت: ويأتي حديثهم بلفظ: [لا يتمنين أحدكم الموت.. ...] رقم ٧٦١١.٢ الأصل [نيل] وهو خطأ."],[7899,"«لا تذكروا هلكاكم إلا بخير» .\n(صحيح) [ن] عن عائشة. الروض النضير ١/٤٣٧."],[7900,"«لا تذهب الدنيا حتى تصير للكع بن لكع» .\n(صحيح) [حم] عن أبي هريرة. المشكاة ٥٣٦٥."],[7901,"٢٥١٢ - «لا تذهب الأيام والليالي حتى تشرب طائفة من أمتي الخمر يسمونها بغير اسمها» .\n(صحيح) [هـ١] عن أبي أمامة. الصحيحة ٩١: حل."],[7902,"٢٥١٣ - «لا تذهب الأيام والليالي حتى يملك رجل يقال له الجهجاه» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ٢٠١٩."],[7903,"٢٥١٤ - «لا تذهب الدنيا ولا تنقضي حتى يملك رجل من أهل بيتي يواطئ اسمه اسمي» .\n(صحيح) [حم د ت] عن ابن مسعود. تخريج الفضائل ص ١٦، المشكاة ٥٤٥٢: حب، ك."],[7904,"«لا ترجعوا بعدي كفارا يضرب بعضكم رقاب بعض» . (الصحيح) [حم ق ن هـ] عن جرير [حم خ د ن هـ] عن ابن عمر [خ ن] عن أبي بكرة [خ ت] عن ابن عباس. الروض النضير ٧٩٧، إيمان أبي عبيد ٧٥، نقد الكتاني ص ٤٠."],[7905,"٢٥١٥ - «لا ترجعوا بعدي كفارا يضرب بعضكم رقاب بعض ولا يؤخذ الرجل بجريرة أبيه ولا بجريرة أخيه» .\n(صحيح) [ن] عن ابن عمر. الصحيحة ١٩٧٤."],[7906,"(١) الأصل [د] وهو خطأ."],[7907,"٢٥١٦ - «لا ترسلوا فواشيكم وصبيانكم إذا غابت الشمس حتى تذهب فحمة العشاء فإن الشياطين تبعث إذا غابت الشمس حتى تذهب فحمة العشاء» .\n(صحيح) [حم م د] عن جابر. إرواء الغليل ٣٩."],[7908,"٢٥١٧ - «لا ترغبوا عن آبائكم فمن رغب عن أبيه فهو كفر» .\n(صحيح) [ق] عن أبي هريرة."],[7909,"٢٥١٨ - «لا ترفعوا أبصاركم إلى السماء في الصلاة أن تلتمع» .\n(صحيح) [هـ طب] عن ابن عمر. صحيح الترغيب ٥٤٩."],[7910,"٢٥١٩ - «لا ترقبوا أموالكم فمن أرقب شيئا فهو لمن أرقبه» .\n(صحيح) [ن] عن ابن عباس. الإرواء ١٦٠٩."],[7911,"٢٥٢٠ - «لا ترقبوا ولا تعمروا فمن أعمر شيئا أو أرقبه فهو للوارث إذا مات» .\n(صحيح) [د ن حب] عن جابر. الإرواء ١٦٠٩."],[7912,"«لا تركبوا الخز ولا النمار» .\n(صحيح) [د] عن معاوية. المشكاة ٤٣٥٧."],[7913,"«لا تزال أمتي بخير ما عجلوا الإفطار.. ...» .\n(صحيح) [حم] عن أبي ذر. الإرواء ٩١٧."],[7914,"«لا تزال أمتي على الفطرة ما لم يؤخروا المغرب إلى اشتباك النجوم» .\n(صحيح) [حم د ك] عن أبي أيوب وعقبة بن عامر ... [هـ] عن العباس. الإرواء ٩١٧، الروض النضير ٣٦٥، المشكاة ٦٠٩، صحيح أبي داود ٤٤٤."],[7915,"٢٥٢١ - «لا تزال جهنم يلقى فيها وتقول:» هل من مزيد حتى يضع فيها رب العزة قدمه فينزوي بعضها إلى بعض وتقول: قط قط وعزتك وكرمك ولا يزال في الجنة فضل حتى ينشئ الله لها خلقا آخر فيسكنهم في فضول الجنة\".\n(صحيح) [حم ق ت] عن أنس. السنة ٥٣١ - ٥٣٤."],[7916,"«لا تزال طائفة من أمتي ظاهرين على الحق حتى تقوم الساعة» .\n(صحيح) [ك] عن عمر. الصحيحة ٢٧٠و ١٩٥٦: الطيالسي، الدارمي."],[7917,"«لا تزال طائفة من أمتي ظاهرين حتى يأتيهم أمر الله وهم ظاهرون» .\n(صحيح) [ق] عن المغيرة. الصحيحة ١٩٥٥: حم."],[7918,"٢٥٢٢ - «لا تزال طائفة من أمتي ظاهرين على الحق لا يضرهم من خذلهم حتى يأتي أمر الله وهم كذلك» .\n(صحيح) [م ت هـ] عن ثوبان. مختصر مسلم ١٠٩٥، الصحيحة ١٩٥٧: حم، د، ك."],[7919,"٢٥٢٣ - «لا تزال طائفة من أمتي قائمة بأمر الله لا يضرهم من خذلهم ولا من خالفهم حتى يأتي أمر الله وهم ظاهرون على الناس» .\n(صحيح) [حم ق] عن معاوية."],[7920,"«لا تزال طائفة من أمتي قوامة على أمر الله لا يضرها من خالفها» .\n(صحيح) [هـ] عن أبي هريرة. الصحيحة ١٩٦٢."],[7921,"٢٥٢٤ - \"لا تزال طائفة من أمتي منصورين لا يضرهم خذلان من خذلهم حتى تقوم الساعة\".\n(صحيح) [هـ حب] عن قرة بن أياس. المصدر نفسه."],[7922,"٢٥٢٥ - «لا تزال طائفة من أمتي يقاتلون على الحق ظاهرين إلى يوم القيامة فينزل عيسى بن مريم فيقول أميرهم: تعال صل لنا فيقول: لا إن بعضكم على بعض أمير تكرمة الله لهذه الأمة» .\n(صحيح) [حم م] عن جابر. مختصر مسلم ٢٠٦١، الصحيحة ١٩٦٠: تخ."],[7923,"٢٥٢٦ - «لا تزال طائفة من أمتي يقاتلون على الحق ظاهرين على من نأوأهم حتى يقاتل آخرهم المسيح الدجال» .\n(صحيح) [حم د ك] عن عمران بن حصين. المشكاة ٣٨١٩، الصحيحة ١٩٥٩."],[7924,"«لا تزال عصابة من أمتي يقاتلون على الحق لا يضرهم من خالفهم حتى تأتيهم الساعة وهم على ذلك» .\n(صحيح) [م] عن عقبة بن عامر. الصحيحة ١١٠٨."],[7925,"٢٥٢٧ - «لا تزال عصابة من أمتي يقاتلون على أمر الله قاهرين لعدوهم لا يضرهم من خالفهم حتى تأتيهم الساعة وهم على ذلك» .\n(صحيح) [م] عن عقبة بن عامر. مختصر مسلم ١٠٩٦، الصحيحة ١١٠٨: ك."],[7926,"٢٥٢٨ - «لا تزكوا أنفسكم الله أعلم بأهل البر منكم سموها زينب» .\n(صحيح) [م د] عن زينب بنت أبي سلمة. مختصر مسلم ١٤٠٧، الصحيحة ٢١٠."],[7927,"٢٥٢٩ - «لا تزوج المرأة المرأة ولا تزوج المرأة نفسها.. ...» .\n(صحيح) [هـ] عن أبي هريرة. الإرواء ١٨٤١."],[7928,"٢٥٣٠ - \"لا تزول قدما ابن آدم يوم القيامة من عند ربه حتى يسأل عن خمس: عن عمره فيم أفناه؟ وعن شبابه فيم أبلاه؟ وعن ماله من أين اكتسبه؟ وفيم أنفقه؟ وماذا عمل فيما علم؟ \".\n(حسن) [ت] عن ابن مسعود. الصحيحة ٩٤٦."],[7929,"٢٥٣١ - «لا تزول قدما عبد حتى يسأل عن أربع: عن عمره فيم أفناه وعن علمه ما فعل فيه وعن ماله من أين اكتسبه وفيم أنفقه وعن جسمه فيم أبلاه» .\n(صحيح) [ت] عن أبي برزة. اقتضاء العلم ١ - ٣، الصحيحة ٩٤٦."],[7930,"«لا تسافر المرأة إلا مع ذي محرم ولا يدخل عليها رجل إلا ومعها محرم» .\n(صحيح) [حم ق] عن ابن عباس. الإرواء ٩٩٥."],[7931,"«لا تسافر المرأة بريدا١ إلا ومعها محرم يحرم عليها» .\n(صحيح) [د ك] عن أبي هريرة. الصحيحة ٢٤٢١: ابن خزيمة، ابن عساكر."],[7932,"«لا تسافر المرأة ثلاثة أيام إلا مع ذي محرم» .\n(صحيح) [حم ق د] عن ابن عمر."],[7933,"٢٥٣٣ - «لا تسافر المرأة مسيرة يومين إلا ومعها زوجها أو ذو محرم منها ولا صوم في يومين: الفطر والأضحى» .\n(صحيح) [خ] عن أبي سعيد."],[7934,"٢٥٣٣ - «لا تسافروا بالقرآن فإني لا آمن أن يناله العدو» .\n(صحيح) [م] عن ابن عمر. الإرواء ٢٥٥٨، ١٣٠٠."],[7935,"٢٥٣٤ - «لا تسأل المرأة طلاق أختها لتستفرغ صحفتها ولتنكح فإن لها ما قدر لها» .\n(صحيح) [خ د] عن أبي هريرة."],[7936,"\"لا تسأل الناس شيئا ولا سوطك وإن سقط منك حتى تنزل إليه فتأخذه\".\n(صحيح) [حم] عن أبي ذر. المشكاة ١٨٥٨، صحيح الترغيب ٨٠٤."],[7937,"(١) قال ابن خزيمة: [هو اثنا عشر ميلا بالهاشمي] ."],[7938,"٢٥٣٥ - «لا تسألوني عن شيء إلى يوم القيامة إلا حدثتكم» .\n(صحيح) [حم ق] عن أنس."],[7939,"٢٥٣٦ - «لا تسبن أحدا ولا تحقرن من المعروف شيئا ولو أن تكلم أخاك وأنت منبسط إليه وجهك إن ذلك من المعروف وارفع إزارك إلى نصف الساق فإن أبيت فإلى الكعبين وإياك وإسبال الإزار فإنه من المخيلة وإن الله لا يحب المخيلة وإن امرؤ شتمك وعيرك بما يعلم فيك فلا تعيره بما تعلم فيه فإنما وبال ذلك عليه» .\n(صحيح) [د] عن جابر بن سليم. الصحيحة ١١٠٩و ١٣٥٢."],[7940,"٢٥٣٧ - «لا تسبوا أصحابي فوالذي نفسي بيده لوأن أحدكم أنفق مثل أحد ذهبا ما بلغ مد أحدهم ولا نصيفه» .\n(صحيح) [حم ق د ت] عن أبي سعيد [م هـ] عن أبي هريرة. مختصر مسلم ١٧٤٦، السنة ٩٨٨: الطيالسي، ابن أبي عاصم - أبي سعيد."],[7941,"«لا تسبوا الأموات فإنهم قد أفضوا إلى ما قدموا» .\n(صحيح) [حم خ ن] عن عائشة. الروض النضير ١/٤٣٧، الصحيحة ٢٣٩٧."],[7942,"«لا تسبوا الأموات فتؤذوا الأحياء» ... [حم ت] عن المغيرة.\n(صحيح) الروض ٣٥٧، الصحيحة ٢٣٧٩: حب، الترغيب ٤/١٧٥."],[7943,"«لا تسبوا الدهر فإن الله هو الدهر» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ١٨١٤."],[7944,"«لا تسبوا الديك فإنه يوقظ للصلاة» .\n(صحيح) [د] عن زيد بن خالد. المشكاة ٤١٣٦."],[7945,"٢٥٣٨ - «لا تسبوا الريح فإذا رأيتم ما تكرهون فقولوا: اللهم إنا نسألك من خير هذا الريح وخير ما فيها وخير ما أمرت به ونعوذ بك من شر هذا الريح وشر ما فيها وشر ما أمرت به» .\n(صحيح) [ت] عن أبي. المشكاة ١٥١٨: حم، خد، الطحاوي."],[7946,"«لا تسبوا الريح فإنها من روح الله تعالى تأتي بالرحمة والعذاب ولكن سلوا الله من خيرها وتعوذوا بالله من شرها» .\n(صحيح) [حم هـ] عن أبي هريرة. الكلم الطيب ١٥٣، المشكاة ١٥١٦."],[7947,"٢٥٣٩ - «لا تسبوا الريح فإنها من روح الله وسلوا الله خيرها وخير ما فيها وخير ما أرسلت به وتعوذوا بالله من شرها وشر ما فيها وشر ما أرسلت به» .\n(صحيح) [ن ك] عن أبي. المشكاة ١٥١٨."],[7948,"«لا تسبوا الشيطان وتعوذوا بالله من شره» .\n(صحيح) [المخلص] عن أبي هريرة. الصحيحة ٢٤٢٢: تمام، الديلمي."],[7949,"«لا تسبوا تبعا فإنه كان قد أسلم» .\n(صحيح) [حم] عن سهل بن سعد. الصحيحة ٢٤٢٣: طس، الروياني، ابن عساكر. أبو بكر بن خلاد، طب، طس، خط، ابن عساكر - ابن عباس. ابن عساكر - وهب بن منبه مرسلا."],[7950,"«لا تسبوا ورقة بن نوفل فإني قد رأيت له جنة أو جنتين» .\n(صحيح) [ك] عن عائشة. الصحيحة ٤٠٥."],[7951,"«لا تسبي الحمى فإنها تذهب خطايا بني آدم كما يذهب الكير خبث الحديد» .\n(صحيح) [م] عن جابر. مختصر مسلم ١٤٦٩، الصحيحة ١٢١٥: خد، ابن سعد."],[7952,"٢٥٤٠ - \"لا تسبي الحمى فإنها تنفي الذنوب كما تنفي النار خبث الحديد\".\n(صحيح) [هـ] عن أبي هريرة. الصحيحة ٢٢١٥."],[7953,"«لا تستبطئوا الرزق فإنه لم يكن عبد ليموت حتى يبلغه آخر رزق هوله فاتقوا الله وأجملوا في الطلب أخذ الحلال وترك الحرام» .\n(صحيح) [ك هق] عن جابر. الترغيب ٣/٧."],[7954,"«لا تستقبلوا السوق ولا تحفلوا ولا ينفق بعضكم لبعض» .\n(حسن) [حم ت] عن ابن عباس. أحاديث البيوع: هق، الضياء."],[7955,"٢٥٤٢ - «لا تستنجوا بالروث ولا بالعظام فإنه زاد إخوانكم من الجن» .\n(صحيح) [ت] عن ابن مسعود. الإرواء ٤٦: م."],[7956,"«لا تسكن الكفور فإن ساكن الكفور كساكن القبور» .\n(حسن) [خد هب] عن ثوبان. الضعيفة ٤٧٨٣."],[7957,"٢٥٤٣ - «لا تسلموا تسليم اليهود والنصارى فإن تسليمهم إشارة بالكفوف.. ...» .\n(حسن) [هب] عن جابر. الصحيحة ١٧٨٣."],[7958,"٢٥٤٤ - «لا تسم غلامك رباحا ولا أفلح ولا يسارا ولا نجيحا يقال: أثم هو فيقال لا» .\n(صحيح) [د ت] عن سمرة. الإرواء ١١٧٧: م."],[7959,"«لا تسم غلامك رباحا ولا يسارا ولا أفلح ولا نافعا» .\n(صحيح) [د م] عن سمرة. المصدر نفسه."],[7960,"«لا تسموا العنب الكرم ولا تقولوا خيبة الدهر فإن الله هو الدهر» .\n(صحيح) [ق] عن أبي هريرة. الروض ٢/٥٢٣ - ٥٢٤."],[7961,"٢٥٤٥ - «لا تشتره ولا تعد في صدقتك وإن أعطاكه بدرهم فإن العائد في صدقته كالعائد في قيئه» .\n(صحيح) [حم ق د ن] عن عمر."],[7962,"«لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام ومسجدي هذا والمسجد الأقصى» .\n(صحيح) [حم ق د ن هـ] عن أبي هريرة [حم ق ت هـ] عن أبي سعيد [هـ] عن ابن عمرو. أحكام الجنائز ص ٢٢٤ - ٢٢٥، الروض ٧١٣، الإرواء ٧٧٣، ٧٩٠، مختصر مسلم ٧٨٩."],[7963,"٢٥٤٦ - «لا تشرب مسكرا فإني حرمت كل مسكر» .\n(صحيح) [ن] عن أبي موسى. الصحيحة ٢٤٢٤."],[7964,"«لا تشربوا الخمر فإنها مفتاح كل شر» .\n(صحيح) [هـ] عن أبي الدرداء. الإرواء ٢٠٢٦، الصحيحة ٧٢٢."],[7965,"٢٥٤٧ - «لا تشربوا في آنية الذهب والفضة ولا تأكلوا في صحافها ولا تلبسوا الحرير ولا الديباج فإنه لهم في الدنيا وهو لكم في الآخرة» .\n(صحيح) [حم ق ٤] عن حذيفة. مختصر مسلم ١٢٨٨، الإرواء ٣٢."],[7966,"٢٥٤٨ - «لا تشربوا في الدباء ولا في المزفت ولا في النقير وانتبذوا في الأسقية فإن اشتد في الأسقية فصبوا عليه الماء إن الله حرم الخمر والميسر والكوبة وكل مسكر حرام» .\n(صحيح) [حم] عن ابن عباس. المشكاة ٤٥٠٣، الصحيحة ٢٤٢٥."],[7967,"٢٥٤٩ - «لا تشربوا في النقير ولا في الدباء ولا في الحنتمة وعليكم بالموكأ» .\n(صحيح) [م] عن أبي سعيد. المصدر نفسه: حم."],[7968,"٢٥٥٠ - «لا تشربوا في نقير ولا مزفت ولا دباء ولا حنتم واشربوا في الجلد الموكأ عليه فإن اشتد فاكسروه بالماء فإن أعياكم فأهريقوه» .\n(صحيح) [د] عن رجل من وفد عبد القيس. المصدر نفسه."],[7969,"٢٥٥١ - «لا تشرك بالله شيئا وإن قطعت وحرقت ولا تترك صلاة مكتوبة متعمدا فمن تركها متعمدا فقد برئت منه الذمة ولا تشرب الخمر فإنها مفتاح كل شر» .\n(صحيح) [هـ] عن أبي الدرداء. صحيح الترغيب ٥٦٦، الإرواء ٢٠٢٦."],[7970,"«لا تشمن ولا تستوشمن» .\n(صحيح) [خ ن] عن أبي هريرة."],[7971,"«لا تصاحب إلا مؤمنا ولا يأكل طعامك إلا تقي» .\n(حسن) [حم د ت حب ك] عن أبي سعيد. المشكاة ٥٠١٨."],[7972,"٢٥٥٢ - «لا تصحب الملائكة رفقة فيها جرس» .\n(صحيح) [حم د] عن أم حبيبة. الصحيحة ١٨٧٣: الدارمي، حب."],[7973,"٢٥٥٣ - «لا تصحب الملائكة رفقة فيها جلجل» .\n(صحيح) [ن] عن ابن عمر. الصحيحة ١٨٧٣: حم."],[7974,"«لا تصحب الملائكة رفقة فيها كلب ولا جرس» .\n(صحيح) [حم م د ت] عن أبي هريرة. مختصر مسلم ١٣٩٠، الصحيحة ١٨٧٣: الدارمي."],[7975,"«لا تصحب الملائكة رفقة فيها جلد نمر» .\n(حسن) [د] عن أبي هريرة. المشكاة ٣٩٢٤."],[7976,"٢٥٥٥ - «لا تصدقوا أهل الكتاب ولا تكذبوهم و﴿قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا﴾ الآية» .\n(صحيح) [خ] عن أبي هريرة. الصحيحة ٤٢٢."],[7977,"٢٥٥٦ - «لا تصروا الإبل والغنم فمن ابتاعها بعد فإنه بخير النظرين بعد أن يحلبها إن شاء أمسك وإن شاء ردها وصاع تمر» .\n(صحيح) [خ] عن أبي هريرة. الإرواء ١٣٢٠."],[7978,"«لا تصلوا إلى قبر ولا تصلوا على قبر» .\n(صحيح) [طب] عن ابن عباس. الصحيحة ١٠١٦، تحذير الساجد ٢٢: الضياء"],[7979,"«لا تصلوا خلف النائم ولا المتحدث» .\n(حسن) [د هق] عن ابن عباس. الإرواء ٣٧٥."],[7980,"«لا تصلوا صلاة في يوم مرتين» .\n(صحيح) [حم د] عن ابن عمر. صحيح أبي داود ٥٩٢، المشكاة ١١٥٧."],[7981,"٢٥٥٧ - «لا تصلوا في مبارك الإبل فإنها من الشياطين وصلوا في مرابض الغنم فإنها بركة» .\n(صحيح) [حم د] عن البراء. صحيح أبي داود ١٧٧."],[7982,"٢٥٥٨ - «لا تصم المرأة وبعلها شاهد إلا بإذنه غير رمضان ولا تأذن في بيته وهو شاهد إلا بإذنه وما أنفقت من كسبه من غير أمره فإن نصف أجره له» .\n(صحيح) [حم ق د ت هـ] عن أبي هريرة. الإرواء ٢٠٠٤، مختصر مسلم ٥٥٤."],[7983,"٢٥٥٩ - \"لا تصوموا حتى تروا الهلال ولا تفطروا حتى تروه فإن غم عليكم فاقدروا له\".\n(صحيح) [ق ن] عن ابن عمر. الإرواء ٩٠٣."],[7984,"٢٥٦٠ - «لا تصوموا قبل رمضان وصوموا لرؤيته وأفطروا لرؤيته فإن حالت دونه غيامة فأكملوا ثلاثين يوما» .\n(صحيح) [ت ن حب] عن ابن عباس. المصدر نفسه."],[7985,"٢٥٦١ - «لا تصوموا هذه الأيام أيام التشريق فإنها أيام أكل وشرب» ... [حم ن] عن حمزة بن عمروالأسلمي [حم ك] عن بديل بن ورقاء.\n(صحيح) الروض النضير ٢/٢٥٠."],[7986,"«لا تصوموا يوم الجمعة إلا وقبله يوم أو بعده يوم» .\n(صحيح) [حم] عن أبي هريرة. الصحيحة ٩٨١: ت، هـ."],[7987,"«لا تصوموا يوم الجمعة مفردا» .\n(صحيح) [حم ن ك] عن جنادة الأزدي. الصحيحة ٩٨١."],[7988,"«لا تصوموا يوم السبت إلا في فريضة وإن لم يجد أحدكم إلا عود كرم أو لحاء شجرة فليفطر عليه» .\n(صحيح) [حم د هـ ك] عن الصماء بنت بسر. الإرواء ٩٦٠."],[7989,"«لا تصومن امرأة إلا بإذن زوجها» .\n(صحيح) [حم د حب ك] عن أبي سعيد. الاصحيحة ٣٩٥، الإرواء ٢٠٠٤."],[7990,"«لا تضربوا إماء الله» .\n(صحيح) [د ن هـ ك] عن إياس بن عبد الله بن أبي ذئاب. المشكاة ٣٢٦١: الدارمي، حب."],[7991,"٢٥٦٢ - «لا تطبخوا في قدور المشركين فإن لم تجدوا غيرها فارحضوها رحضا حسنا ثم اطبخوا وكلوا» .\n(صحيح) [هـ] عن أبي ثعلبة الخشني. الإرواء ٣٧."],[7992,"«لا تطرقوا النساء ليلا» ... [طب] عن ابن عباس.\n(صحيح) حم/ ٣٩١ جابر١. ك ٤/٢٩٣ - عبد الله بن رواجة."],[7993,"٢٥٦٣ - «لا تطروني كما أطرت النصارى ابن مريم فإنما أنا عبد فقولوا: عبد الله ورسوله» .\n(صحيح) [خ] عن عمر."],[7994,"«لا تطعموا المساكين مما لا تأكلون» .\n(حسن) [حم] عن عائشة. الصحيحة ٢٤٢٦: طس."],[7995,"٢٥٦٤ - «لا تعاد الصلاة في يوم مرتين» .\n(صحيح) [ن] عن ابن عمر. صحيح أبي داود ٥٩٢."],[7996,"«لا تعجبوا بعمل عامل حتى تنظروا بم يختم له» .\n(صحيح) [طب] عن أبي أمامة. الصحيحة ١٣٣٤: حم، ابن أبي عاصم - أنس."],[7997,"«لا تعذبوا بعذاب الله» .\n(صحيح) [د ت ك] عن ابن عباس. خ: استتابة."],[7998,"«لا تعذبوا صبيانكم بالغمز من العذرة وعليكم بالقسط» .\n(صحيح) [خ] عن أنس."],[7999,"«لا تعزروا فوق عشرة أسواط» .\n(صحيح) [هـ] عن أبي هريرة. ق - أبي بردة بن نبار٢."],[8000,"٢٥٦٥ - «لا تعلموا العلم لتباهوا به العلماء أو تماروا به السفهاء ولا لتجترئوا به المجالس فمن فعل ذلك فالنار النار» .\n(صحيح) [هـ حب ك] عن جابر. صحيح الترغيب ١٠٢."],[8001,"(١) قلت: وقد مضى من رواية الشيخين وأحمد أيضا بنحوه رقم ٣٥٦.٢ بلفظ [لا يجلد.. ...] وسيأتي بإذن الله برقم ٧٦٢٣."],[8002,"٢٥٦٦ - «لا تعمل المطي إلا إلى ثلاثة مساجد: إلى المسجد الحرام وإلى مسجدي هذا وإلى مسجد بيت المقدس» .\n(صحيح) [مالك ٣ حب] عن بصرة بن أبي بصرة [د١ ن] عن أبي بصرة. أحكام الجنائز ٢٢٦: الطيالسي، حم."],[8003,"٢٥٦٧ - «لا تغزى مكة بعد اليوم إلى يوم القيامة» .\n(صحيح) [حم ت حب ك] عن الحارث بن مالك الليثي. الصحيحة ٢٤٢٧: الطحاوي، ابن سعد."],[8004,"«لا تغضب» .\n(صحيح) [حم خ ت] عن أبي هريرة [حم ك] عن جارية بن قدامة."],[8005,"«لا تغضب ولك الجنة» .\n(صحيح) [ابن أبي الدنيا طب] عن أبي الدرداء. الترغيب ٣/٢٧٧."],[8006,"٢٥٦٨ - «لا تغلبنكم الأعراب على اسم صلاتكم العشاء فإنها في كتاب الله: العشاء وهم يعتمون بحلاب الإبل» .\n(صحيح) [حم م د ن هـ ن] عن ابن عمر. مختصر مسلم ٢٢٥."],[8007,"٢٥٦٩ - «لا تغلبنكم الأعراب على اسم صلاتكم فإنما هي: العشاء وإنما يقولون: العتمة لإعتامهم بالإبل» .\n(صحيح) [هـ] عن أبي هريرة."],[8008,"٢٥٧٠ - «لا تفضلوا بين أنبياء الله فإنه ينفخ في الصور فيصعق من في السموات ومن في الأرض إلا ما شاء الله ثم ينفخ فيه أخرى فأكون أول من بعث فإذا موسى آخذ بالعرش فلا أدري أحوسب بصعقته يوم الطور أم بعث قبلي ولا أقول إن أحدا أفضل من يونس بن متى» .\n(صحيح) [ق] عن أبي هريرة. شرح الطحاوية ١٢٨و ٥٥٣/١."],[8009,"(١) الأصل [هـ] وهو خطأ."],[8010,"٢٥٧١ - «لا تفعل بع الجميع بالدراهم ثم ابتع بالدراهم جنيبا» .\n(صحيح) [ق ن] عن أبي سعيد وأبي هريرة. الإرواء ١٣٤٠."],[8011,"«لا تفعل فإن مقام أحدكم في سبيل الله أفضل من صلاته في بيته سبعين عاما ألا تحبون أن يغفر الله لكم ويدخلكم الجنة؟ اغزوا في سبيل الله من قاتل في سبيل الله فواق ناقة وجبت له الجنة» .\n(حسن) [ت ك] عن أبي هريرة. المشكاة ٣٨٣٠، الترغيب ٢/١٧٤."],[8012,"٢٥٧٣ - «لا تفعلوا كما تفعل أهل فارس بعظمائها» .\n(صحيح) [هـ] عن أبي أمامة. م ٢/١٩، ع ٢/٥١٩ - جابر١."],[8013,"«لا تقام الحدود في المساجد ولا يقتل الوالد بالولد» .\n(حسن) [حم ت ك] عن ابن عباس. الإرواء ٢٢١٤، ٢٣٢٧."],[8014,"٢٥٧٤ - «لا تقبل صلاة أحدكم إذا أحدث حتى يتوضأ» .\n(صحيح) [م] عن أبي هريرة."],[8015,"«لا تقبل صلاة الحائض إلا بخمار» .\n(صحيح) [حم ت هـ] عن عائشة. المشكاة ٢٧٦٢، صحيح أبي داود ٦٤٨، الإرواء ١٩٦."],[8016,"«لا تقبل صلاة بغير طهور ولا صدقة من غلول» .\n(صحيح) [م ت هـ] عن ابن عمر."],[8017,"٢٥٧٥ - «لا تقبل صلاة لامرأة تتطيب لهذا المسجد حتى ترجع فتغتسل غسلها من الجنابة» .\n(صحيح) [ذ] عن أبي هريرة. الصحيحة ١٠٣١."],[8018,"٢٥٧٦ - \"لا تقتسم ذريتي دينارا ما تركت بعد نفقة نسائي ومؤنة عاملي فهو صدقة\".\n(صحيح) [حم ق د] عن أبي هريرة. الصحيحة ٢٠٣٨."],[8019,"(١) قلت: مضى حديثه برقم ١٤٣٧ وهو أتم، ولفظه عند [ع] مطابق للفظ أبي أمامة تماما."],[8020,"٢٥٧٧ - «لا تقتل نفس ظلما إلا كان على ابن آدم الأول كفل من دمها لأنه أول من سن القتل» .\n(صحيح) [حم ق ت ن هـ] عن ابن مسعود. مختصر مسلم ١٠٢٥."],[8021,"«لا تقتلوا الجراد فإنه من جند الله الأعظم» .\n(حسن) [طب هب] عن أبي زهير. الصحيحة ٢٤٢٨: طس، أبو محمد المخلدي، ابن منده."],[8022,"٢٥٧٨ - «لا تقتلوا الجنان إلا كل أبتر ذي طفيتين فإنه يسقط الولد ويذهب البصر فاقتلوه» .\n(صحيح) [خ] عن أبي لبابة."],[8023,"«لا تقتلوا الضفادع ... ...» .\n(صحيح) [ن] عن ابن عمر. الروض النضير ٥٩٤، الضعيفة ٤٧٨٨."],[8024,"٢٥٧٩ - «لا تقتلوا أولادكم سرا فو الذي نفسي بيده إن الغيل ليدرك الفارس فيدعثره عن فرسه» .\n(حسن) [حم د هـ] عن أسماء بنت يزيد. المشكاة ٣١٩٦."],[8025,"٢٥٨٠ - «لا تقدموا الشهر بصيام يوم ولا يومين إلا أن يكون شيء يصومه أحدكم لا تصوموا حتى تروه ثم صوموا حتى تروه فإن حال دونه غمام فأتموا العدة ثلاثين ثم أفطروا والشهر تسع وعشرون» .\n(صحيح) [د] عن ابن عباس. الإرواء ٩٠٢: حم، ن، ت، الدارمي، ك."],[8026,"٢٥٨١ - «لا تقدموا الشهر بيوم ولا يومين إلا أن يوافق ذلك صوما كان يصومه أحدكم صوموا لرؤيته وأفطروا لرؤيته فإن غم عليكم فعدوا ثلاثين ثم أفطروا» .\n(صحيح) [ت] عن أبي هريرة. الإرواء ٩٠٢: حم، قط."],[8027,"«لا تقدموا الشهر حتى تروا الهلال أو تكملوا العدة قبله ثم صوموا حتى تروا الهلال أو تكملوا العدة قبله» .\n(صحيح) [د ن حب] عن حذيفة. المصدر ذاته."],[8028,"٢٥٨٢ - «لا تقدموا شهر رمضان بصوم قبله بيوم أو يومين إلا أن يكون رجل كان يصوم صوما فليصمه» .\n(صحيح) [حم م ٤] عن أبي هريرة. مختصر مسلم ٥٧٣، الصحيحة ٢٣٩٨: الطيالسي، هق."],[8029,"«لا تقص الرؤيا إلا على عالم أو ناصح» .\n(صحيح) [ت] عن أبي هريرة. الروض ١١٦٢، الصحيحة ١١٩، ١١٢٠: الدارمي، طص، أبو الشيخ، ك - أنس."],[8030,"«لا تقطع الأيدى في السفر» .\n(صحيح) [حم ٣ الضياء] عن بسر بن أبي أرطاة. المشكاة ٣٦٠١."],[8031,"٢٥٨٣ - «لا تقطع اليد في تمر معلق فإن ضمه الجرين قطعت في ثمن المجن ولا تقطع في حريسة الجبل فإذا أوى المراح قطعت في ثمن المجن» .\n(حسن) [ن] عن ابن عمرو. الإرواء ٢٤١٣: هق."],[8032,"«لا تقطع يد السارق إلا في ربع دينار فصاعدا» .\n(صحيح) [م ن هـ] عن عائشة. مختصر مسلم ١٠٤٣، الروض ٧٨٣، الإرواء ٢٤٠٨: حم."],[8033,"٢٥٨٤ - «لا تقعدوا على القبور» ... [حم١ ن] عن عمروبن حزم.\n(صحيح) اجكام الجنائز ٢٠٩ - ٢١٠\" حم، م - أبي مرثد٢."],[8034,"(١) الأصل [م، ن] والتصويب من [الزيادة] .٢ وقد مضى حديثه بلفظ [لا تجلسوا على.. ...] ."],[8035,"٢٥٨٥ - «لا تقل تعس الشيطان فإنه يعظم حتى يصير مثل البيت ويقول: بقوتي صرعته ولكن قل: باسم الله فإنك إذا قلت ذلك تصاغر حتى يصير مثل الذباب» .\n(صحيح) [حم د ن ك] عن والد أبي المليح. الكلم الطيب ٢٣٧."],[8036,"٢٥٨٩ - «لا تقل عليك السلام فإن عليك السلام تحية الموتى ولكن قل: السلام عليك» .\n(صحيح) [٣ ك] عن جابر بن سليم. الصحيحة ١٤٠٣: حم."],[8037,"٢٥٨٧ - «لا تقولوا السلام على الله فإن الله هوالسلام ولكن قولوا: التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين فإنكم إذا قلتم ذلك أصاب كل عبد في السماء والأرض أشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله ثم يتخير من الدعاء أعجبه إليه فيدعو به» .\n(صحيح) [حم ق د ن هـ] عن ابن مسعود. صحيح أبي داود ٨٨٩، الإرواء ٣١٩."],[8038,"٢٥٨٨ - «لا تقولوا: الكرم ولكن قولوا: العنب والحبلة» .\n(صحيح) [م] عن وائل. مختصر مسلم ١٤٠٩."],[8039,"٢٥٨٩ - «لا تقولوا للمنافق: سيدنا فإنه إن يكن سيدكم فقد أسخطتم ربكم» .\n(صحيح) [حم د ن] عن بريدة. الصحيحة ٣٧٠: خد، ابن السني، هب."],[8040,"٢٥٩٠ - «لا تقولوا: ما شاء الله وشاء فلان ولكن قولوا: ما شاء الله ثم شاء فلان» .\n(صحيح) [حم د ن] عن حذيفة. الصحيحة ١٣٧."],[8041,"«لا تقوم الساعة إلا على شرار الناس» .\n(صحيح) [حم م] عن ابن مسعود. مختصر مسلم ٢٠٢٢."],[8042,"٢٥٩١ - «لا تقوم الساعة حتى تأخذ أمتي أخذ القرون قبلها شبرا بشبر وذراعا بذراع قيل يا رسول الله! كفارس والروم؟ قال: ومن الناس إلا أولئك؟» .\n(صحيح) [خ] عن أبي هريرة."],[8043,"«لا تقوم الساعة حتى تخرج نار من أرض الحجاز تضيء أعناق الإبل ببصرى» .\n(صحيح) [ق] عن أبي هريرة. مختصر مسلم ٢٠١١."],[8044,"٢٥٩٣ - «لا تقوم الساعة حتى تضطرب أليات دوس حول ذي الخلصة» .\n(صحيح) [حم ق] عن أبي هريرة. السنة ٧٧ - ٧٩: ابن أبي عاصم عنه وعن ابن عباس. مختصر مسلم."],[8045,"٢٥٩٤ - «لا تقوم الساعة حتى تطلع الشمس من مغربها فإذا طلعت فرآها الناس آمنوا أجمعون فذلك حين لا ينفع نفسا إيمانها لم تكن آمنت من قبل أو كسبت في إيمانها خيرا ولتقومن الساعة وقد نشر الرجلان ثوبهما بينهما فلا يتبايعانه ولا يطويانه ولتقومن الساعة وقد انصرف الرجل بلبن لقحته فلا يطعمه ولتقومن الساعة وهو يليط حوضه فلا يسقي فيه ولتقومن الساعة وقد رفع أكلته إلى فيه فلا يطعمها» .\n(صحيح) [ق هـ] عن أبي هريرة."],[8046,"٢٥٩٥ - «لا تقوم الساعة حتى تطلع الشمس من مغربها فإذا طلعت من مغربها ورآها الناس آمنوا أجمعون فذلك حين لا ينفع نفسا إيمانها لم تكن آمنت من قبل» .\n(صحيح) [حم ق د هـ] عن أبي هريرة. شرح الطحاوية ٧٦٥."],[8047,"٢٥٩٦ - \"لا تقوم الساعة حتى تقاتلوا الترك صغار الأعين حمر الوجوه زلف الأنوف كأن وجوههم المجان المطرقة ولا تقوم الساعة حتى تقاتلوا قوما نعالهم الشعر وليأتين على أحدكم زمان لأن يراني أحب إليه من أن يكون له مثل أهله وماله\".\n(صحيح) [ق د ت هـ] عن أبي هريرة."],[8048,"٢٥٩٧ - «لا تقوم الساعة حتى تقاتلوا اليهود حتى يقول الحجر وراءه اليهودي: يا مسلم هذا يهودي ورائي فاقتله» .\n(صحيح) [ق] عن أبي هريرة."],[8049,"٢٥٩٨ - «لا تقوم الساعة حتى تقاتلوا خوزا وكرمان من الأعاجم حمر الوجوه فطس الأنوف صغار الأعين كأن وجوههم المجان المطرقة نعالهم الشعر» .\n(صحيح) [حم خ] عن أبي هريرة."],[8050,"٢٥٩٩ - «لا تقوم الساعة حتى تقاتلوا قوما صغار الأعين عراض الوجوه كأن أعينهم حدق الجراد كأن وجوههم المجان المطرقة ينتعلون الشعر ويتخذون الدرق حتى يرتبطوا خيولهم بالنخل» .\n(صحيح) [حم هـ حب] عن أبي سعيد. الصحيحة ٢٤٢٩."],[8051,"٢٦٠٠ - «لا تقوم الساعة حتى تقتل فئتان عظيمتان دعواهما واحدة ولا تقوم الساعة حتى يبعث دجالون كذابون قريبا من ثلاثين كلهم يزعم أنه رسول الله» ... [حم ق د ت] عن أبي هريرة.\n(صحيح) مختصر مسلم ٢٠٠٧، ٢٠٢٣، الصحيحة ١٦٨٣."],[8052,"٢٦٠١ - «لا تقوم الساعة حتى تلحق قبائل من أمتي بالمشركين وحتى تعبد الأوثان وإنه سيكون في أمتي ثلاثون كذابا كلهم يزعم أنه نبي وأنا خاتم النبيين لا نبي بعدي» .\n(صحيح) [ت ك] عن ثوبان. المشكاة ٤٥٠٦، الصحيحة ١٦٨٣: د، هـ."],[8053,"«لا تقوم الساعة حتى لا يحج البيت» .\n(صحيح) [ع ك] عن أبي سعيد. الصحيحة ٢٤٣٠: حب."],[8054,"«لا تقوم الساعة حتى لا يقال في الأرض: الله الله» .\n(صحيح) [حم م ت] عن أنس. مختصر مسلم ٢٠٢٠، ك ٤/٤٩٤، حب ١٩١١."],[8055,"«لا تقوم الساعة حتى يتباهى الناس في المساجد» .\n(صحيح) [حم حب] عن أنس. الروض النضير ١٣٨، صحيح أبي داود ٤٧٥."],[8056,"٢٦٠٢ - «لا تقوم الساعة حتى يتقارب الزمان فتكون السنة كالشهر والشهر كالجمعة وتكون الجمعة كاليوم ويكون اليوم كالساعة وتكون الساعة كالضرمة بالنار» .\n(صحيح) [حم ت] عن أنس. المشكاة ٥٤٤٨: حم، حب - عن أبي هريرة."],[8057,"٢٦٠٣ - «لا تقوم الساعة حتى يحسر الفرات عن جبل من ذهب يقتتل الناس عليه فيقتل من كل مائة تسعة وتسعون ويقول كل رجل منهم: لعلي أكون أنا الذي أنجو» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ٢٠١٥."],[8058,"٢٦٠٤ - «لا تقوم الساعة حتى يحسر الفرات عن جبل من ذهب يقتتل عليه الناس فيقتل تسعة أعشارهم» .\n(صحيح) [هـ] عن أبي هريرة [طب] عن أبي. يشهد له ما قبله."],[8059,"٢٦٠٥ - «لا تقوم الساعة حتى يخرج رجل من قحطان يسوق الناس بعصاه» .\n(صحيح) [ق] عن أبي هريرة. مختصر مسلم ٢٠١٨."],[8060,"٢٦٠٦ - \"لا تقوم الساعة حتى يقاتل المسلمون الترك؛ قوما وجوههم كالمجان المطرقة يلبسون الشعر ويمشون في الشعر\".\n(صحيح) [م د ن] عن أبي هريرة."],[8061,"٢٦٠٧ - «لا تقوم الساعة حتى يقاتل المسلمون اليهود فيقتلهم المسلمون حتى يختبئ اليهودي من وراء الحجر والشجر فيقول الحجر أو الشجر: يا مسلم! يا عبد الله! هذا يهودي خلفي فتعال فاقتله إلا الغرقد فإنه من شجر اليهود» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ٢٠٢٥، الصحيحة ٢٤٥٧."],[8062,"٢٦٠٨ - «لا تقوم الساعة حتى يقبض العلم وتكثر الزلازل ويتقارب الزمان وتظهر الفتن ويكثر الهرج: وهو القتل» .\n(صحيح) [حم خ هـ] عن أبي هريرة. العلم لأبي خيثمة ١١٨."],[8063,"٢٦٠٩ - «لا تقوم الساعة حتى يكثر المال ويفيض حتى يخرج الرجل بزكاة ماله فلا يجد أحدا يقبلها منه وحتى تعود أرض العرب مروجا وأنهارا» .\n(صحيح) [م] عن أبي هريرة. نقد الكتاني ٤١."],[8064,"٢٦١٠ - «لا تقوم الساعة حتى يكثر المال فيكم فيفيض حتى يهم رب المال من يقبل صدقته وحتى يعرضه فيقول الذي يعرضه عليه: لا أرب لي فيه» .\n(صحيح) [ق] عن أبي هريرة. المشكاة ١٢٩."],[8065,"«لا تقوم الساعة حتى يكون أسعد الناس بالدنيا لكع ابن لكع» .\n(صحيح) [حم ت الضياء] عن حذيفة. المشكاة ٥٣٦٥."],[8066,"«لا تقوم الساعة حتى يمر الرجل بقبر الرجل فيقول يا ليتني مكانه» .\n(صحيح) [حم ق] عن أبي هريرة. الصحيحة ٥٧٨."],[8067,"٢٦١١ - «لا تقوم الساعة حتى ينزل الروم بالأعماق أو بدابق فيخرج إليهم جيش من المدينة من خيار أهل الأرض يومئذ فإذا تصافوا قالت الروم: خلوا بيننا وبين الذين سبوا منا نقاتلهم فيقول المسلمون: لا والله لا نخلي بينكم وبين إخواننا فيقاتلونهم فينهزم ثلث لا يتوب الله عليهم أبدا ويقتل ثلث هم أفضل الشهداء عند الله ويفتتح الثلث لا يفتنون أبدا ; فيفتتحون القسطنطينية فبينما هم يقتسمون الغنائم قد علقوا سيوفهم بالزيتون إذ صاح فيهم الشيطان: إن المسيح قد خلفكم في أهليكم فيخرجون وذلك باطل فإذا جاءوا الشام خرج فبينما هم يعدون للقتال يسوون الصفوف إذ أقيمت الصلاة فينزل عيسى بن مريم فأمهم فإذا رآه عدوالله ذاب كما يذوب الملح في الماء فلوتركه لا نذاب حتى يهلك ولكن يقتله الله بيده فيريهم دمه في حربته» .\n(صحيح) [م] عن أبي هريرة. مختصر ٢٠٢٩، الصحيحة ٢٤٥٧."],[8068,"٢٦١٢ - «لا تكتبوا عني شيئا إلا القرآن فمن كتب عني غير القرآن فليمحه وحدثوا عني ولا حرج ومن كذب علي متعمدا فليتبوأ مقعده من النار» .\n(صحيح) [حم م] عن أبي سعيد. مختصر مسلم ١٨٦١، ك ١/١٢٧."],[8069,"٢٦١٣ - «لا تكثر الضحك فإن كثرة الضحك تميت القلب» .\n(صحيح) [هـ] عن أبي هريرة. الصحيحة ٥٠٥."],[8070,"٢٦١٤ - «لا تكذبوا علي فإن الكذب يولج النار» ١.\n(صحيح) [هـ] عن علي. مش ١/١٦٦."],[8071,"(١) قلت: هذا هو الحديث الذي بعده فلا داعي لتكراره."],[8072,"٢٦١٥ - «لا تكذبوا علي فإنه من يكذب علي فليلج النار» .\n(صحيح) [حم ق ت] عن علي."],[8073,"«لا تكروا الأرض.. ...» .\n(صحيح) [ن] عن رافع بن خديج. الإرواء ١٤٧٨."],[8074,"«لا تكرهوا مرضاكم على الطعام والشراب فإن الله يطعمهم ويسقيهم» ... [ت هـ ك] عن عقبة بن عامر.\n(حسن) المشكاة ٤٥٣٣، الصحيحة ٧٢٧: عد، الروياني. ك - عبد الرحمن بن عوف."],[8075,"«لا تكشف فخذك ولا تنظر إلى فخذ حي ولا ميت» .\n(صحيح) [د] عن علي. الإرواء ٢٦٩."],[8076,"«لا تكلفوا للضيف» .\n(صحيح) [ابن عساكر] عن سلمان. الصحيحة ٢٣٩٢: ك، عد."],[8077,"٢٦١٨ - «لا تكونوا عون الشيطان على أخيكم» .\n(صحيح) [خ] عن أبي هريرة. المشكاة ٣٦٢١."],[8078,"«لا تلاعنوا بلعنة الله ولا بغضبه ولا بالنار» .\n(حسن) [د ت ك] عن سمرة. الصحيحة ٨٩٠."],[8079,"٢٦١٩ - «لا تلبسوا الحرير فإنه من لبسه في الدنيا لم يلبسه في الآخرة» .\n(صحيح) [م] عن ابن الزبير. مختصر مسلم ١٣٣٦، الإرواء ٢٧٨."],[8080,"٢٦٢٠ - \"لا تلبسوا القميص ولا العمائم ولا السراويلات ولا البرانس ولا الخفاف إلا أحد لا يجد النعلين فليلبس الخفين وليقطعهما أسفل من الكعبين ولا تلبسوا من الثياب شيئا مسه زعفران أو ورس ولا تنتقب المرأة المحرمة ولا تلبس القفازين\".\n(صحيح) [خ ت ن] عن ابن عمر. مختصر مسلم ٦٧٨."],[8081,"٢٦٢١ - «لا تلحفوا في المسألة فوالله لا يسألني أحد منكم شيئا فتخرج له مسألته مني شيئا وأنا له كاره فيبارك له فيما أعطيته» .\n(صحيح) [حم م ن] عن معاوية. مختصر ٥٥٧."],[8082,"٢٦٢٢ - «لا تلعن الريح فإنها مأمورة وإنه من لعن شيئا ليس له بأهل رجعت اللعنة عليه» .\n(صحيح) [د ت] عن ابن عباس. الصحيحة ٥٢٧: حب، طب، هق."],[8083,"٢٦٢٣ - «لا تلقوا الجلب فمن تلقى فاشترى منه شيئا فصاحبه بالخيار إذا أتى السوق» ... [حم م ت ن هـ] عن أبي هريرة.\n(صحيح) مختصر مسلم ٩٤١، الإرواء ١٣١٧، أحاديث البيوع."],[8084,"٢٦٢٤ - «لا تلقوا الركبان للبيع ولا يبع بعضكم على بيع بعض ولا تناجشوا ولا يبع حاضر لباد ولا تصروا الغنم ومن ابتاعها فهو بخير النظرين بعد أن يحلبها إن رضيها أمسكها وإن سخطها ردها وصاعا من تمر» .\n(صحيح) [خ د ن] عن أبي هريرة. أحاديث البيوع."],[8085,"٢٦٢٥ - «لا تلقوا الركبان ولا يبع حاضر لباد» .\n(صحيح) [ق] عن ابن عباس. أحاديث البيوع."],[8086,"٢٦٢٦ - «لا تمثلوا بالبهائم» .\n(صحيح) [ن] عن عبد الله بن جعفر. الصحيحة ٢٤٣١: ابن عساكر - ابن عمر."],[8087,"٢٦٢٧ - «لا تمسح وأنت تصلي فإن كنت لا بد فاعلا فواحدة. تسوية الحصى١» .\n(حسن) [د] عن معيقيب. صحيح أبي داود ٨٧٢: ق."],[8088,"(١) زيادة من [د] ."],[8089,"٢٦٢٨ - «لا تمش في نعل واحدة ولا تحتب في ثوب واحد ولا تأكل بشمالك ولا تشتمل الصماء ولا تضع إحدى رجليك على الأخرى إذا استلقيت» .\n(صحيح) [م] عن جابر. مختصر مسلم ١٣٥٥."],[8090,"٢٦٢٩ - «لا تمنعوا النساء حظوظهن من المساجد إذا استأذنكم» .\n(صحيح) [م] عن ابن عمر. تخ ٤/٢/٣٥٧."],[8091,"٢٦٣٠ - «لا تمنعوا إماء الله أن يصلين في المسجد» .\n(صحيح) [هـ] عن ابن عمر. غاية المرام ٢٠٢، صحيح أبي داود ٥٧٥، الإرواء ٥١٥: خ."],[8092,"«لا تمنعوا إماء الله مساجد الله» .\n(صحيح) [حم م] عن ابن عمر. المصادر نفسها."],[8093,"٢٦٣١ - «لا تمنعوا إماء الله مساجد الله ولكن ليخرجن وهن تفلات» .\n(صحيح) [حم د] عن أبي هريرة. الإرواء ٥١٥، صحيح أبي داود ٥٧٤."],[8094,"٢٦٣٢ - «لا تمنعوا نساءكم المساجد وبيوتهن خير لهن» .\n(صحيح) [حم د ك] عن ابن عمر. صحيح أبي داود ٥٧٦، الإرواء ٥١٥."],[8095,"٢٦٣٣ - «لا تنبذوا التمر والبسر جميعا وانبذوا كل واحد منهما على حدته» .\n(صحيح) [هـ] عن أبي هريرة. م ٦/٩١ - ٩٢."],[8096,"٢٦٣٤ - «لا تنبذوا في الدباء ولا المزفت» .\n(صحيح) [ق] عن أنس."],[8097,"٢٦٣٥ - «لا تنتبذوا الزهووالرطب جميعا ولا تنتبذوا التمر والزبيب جميعا وانتبذوا كل واحد منهما على حدته» .\n(صحيح) [ن هـ] عن أبي قتادة. م ٦/٩١."],[8098,"٢٦٣٦ - «لا تنتبذوا في الدباء ولا المزفت ولا النقير وكل مسكر حرام» .\n(صحيح) [ن] عن عائشة. م ٦/٩٣ - ٩٤و ٩٩."],[8099,"٢٦٣٧ - «لا تنتفوا الشيب ما من مسلم يشيب شيبة في الإسلام إلا كانت له نورا يوم القيامة» .\n(صحيح) [د] عن ابن عمر. المشكاة ٤٤٥٨."],[8100,"٢٦٣٨ - «لا تنتهي البعوث عن غزو هذا البيت حتى يخسف بجيش منهم» .\n(صحيح) [ن ك] عن أبي هريرة. الصحيحة ٢٤٣٢."],[8101,"٢٦٣٩ - «لا تنتهي الناس عن غزو هذا البيت حتى يغزوجيش حتى إذا كانوا بالبيداء أو ببيداء من الأرض خسف بأولهم وآخرهم ولم ينج أوسطهم قيل: فإن كان فيهم من يكره؟ قال: يبعثهم الله على ما في أنفسهم» .\n(صحيح) [حم ت ن هـ] عن صفية. الصحيحة ٢٤٣٢."],[8102,"٢٦٤٠ - «لا تنذروا فإن النذر لا يغني من القدر شيئا وإنما يستخرج به من البخيل» .\n(صحيح) [م ت ن] عن أبي هريرة. الإرواء ٢٥٨٥."],[8103,"«لا تنزع الرحمة إلا من شقي» .\n(حسن) [حم د ت حب ك] عن أبي هريرة. المشكاة ٤٩٦٨."],[8104,"٢٦٤١ - \"لا تنزلوا على جواد الطريق ولا تقضوا عليها الحاجات\".\n(صحيح) [هـ] عن جابر. الصحيحة ٢٤٣٣: ابن أبي شيبة، حم، ع١."],[8105,"٢٦٤٢ - «لا تنقطع الهجرة حتى تنقطع التوبة ولا تنقطع التوبة حتى تطلع الشمس من مغربها» .\n(صحيح) [حم د] عن معاوية. المشكاة ٢٣٤٦، الإرواء ١٢٠٨."],[8106,"٢٦٤٣ - «لا تنكح الأيم حتى تستأمر ولا تنكح البكر حتى تستأذن قيل: وكيف إذنها؟ قال: أن تسكت» .\n(صحيح) [ق د ن] عن أبي هريرة. مختصر مسلم ٨٠٢، الإرواء ١٨٢٨."],[8107,"٢٦٤٤ - «لا تنكح الثيب حتى تستأمر ولا تنكح البكر حتى تستأذن وإذنها الصموت» .\n(صحيح) [ت هـ] عن أبي هريرة. الإرواء ١٨٢٨."],[8108,"٢٦٤٥ - «لا تنكح العمة على ابنة الأخ ولا ابنة الأخت على الخالة» .\n(صحيح) [م] عن أبي هريرة. الإرواء ١٨٨٢."],[8109,"٢٦٤٦ - «لا تنكح المرأة على عمتها ولا العمة على ابنة أخيها ولا المرأة على خالتها ولا الخالة على بنت أختها لا الكبرى على الصغرى ولا الصغرى على الكبرى» .\n(صحيح) [د] عن أبي هريرة. الإرواء ١٨٨٢."],[8110,"٢٦٤٧ - «لا تنكح المرأة على عمتها ولا على خالتها» .\n(صحيح) [ن هـ] عن أبي هريرة [ن هـ] عن جابر [هـ] عن أبي موسى وأبي سعيد. المصدر نفسه: ق."],[8111,"٢٦٤٨ - \"لا تنهكي فإن ذلك أحظى للمرأة وأحب إلى البعل\".\n(صحيح) [د] عن أم عطية. الصحيحة ٧٢١."],[8112,"(١) قلت: واللفظ لابن أبي شيبة، وعزوه لـ[هـ] وهم من السيوطي كما نبهت عليه هناك."],[8113,"٢٦٤٩ - «لا تواصلوا إني لست كأحد منكم إني أطعم وأسقى» .\n(صحيح) [خ ت] عن أنس."],[8114,"٢٦٥٠ - «لا تواصلوا فأيكم أراد أن يواصل فليواصل حتى السحر إني لست كهيئتكم إني أبيت لي مطعم يطعمني وساق يسقيني» .\n(صحيح) [حم خ د] عن أبي سعيد."],[8115,"«لا توصل صلاة بصلاة حتى تتكلم أو تخرج» .\n(صحيح) [حم د] عن معاوية. صحيح أبي داود ١٠٣٤، الإرواء ٤٤٤: م."],[8116,"٢٦٥١ - «لا توطأ حامل حتى تضع ولا غير ذات حمل حتى تحيض» .\n(صحيح) [حم د ك] عن أبي سعيد. المشكاة ٢٣٣٨، الإرواء ١٨٧."],[8117,"٢٦٥٢ - «لا توعي فيوعي الله عليك ارضخي ما استطعت» .\n(صحيح) [خ] عن أسماء بنت أبي بكر."],[8118,"٢٦٥٣ - «لا توكئ فيوكأ عليك» .\n(صحيح) [خ ت] عن أسماء بنت أبي بكر."],[8119,"٢٦٥٤ - «لا تهاجروا ولا تدابروا ولا تجسسوا ولا يبع بعضكم على بيع بعض وكونوا عباد الله إخوانا» .\n(صحيح) [م] عن أبي هريرة. أحاديث البيوع."],[8120,"٢٦٥٥ - «لا جلب ولا جنب في الرهان» .\n(صحيح) [د] عن عمران بن حصين. المشكاة ٢٩٤٧."],[8121,"٢٦٥٦ - «لا جلب ولا جنب ولا تؤخذ صدقاتهم إلا في دورهم» .\n(صحيح) [د] عن ابن عمرو. المشكاة ١٧٨٦."],[8122,"«لا جلب ولا جنب ولا شغار في الإسلام» .\n(صحيح) [ن الضياء] عن أنس. المشكاة ١٧٨٦."],[8123,"٢٦٥٧ - «لا جلب ولا جنب ولا شغار في الإسلام ومن انتهب نهبة فليس منا» .\n(صحيح) [حم ت ن] عن عمران بن حصين. المشكاة ٢٩٤٧."],[8124,"٢٦٥٨ - «لا حسد إلا في اثنتين١: رجل آتاه الله القرآن فهو يقوم به آناء الليل وآناء النهار ورجل آتاه الله مالا فهو ينفقه آناء الليل وآناء النهار» ... [حم ق ت هـ] عن ابن عمر.\n(صحيح) حم ٢/٩، ٣٦، خ ٤/٤٩١، مختصر مسلم ٢١٠٨، هـ ٤٢٠٩."],[8125,"٢٦٥٩ - «لا حسد إلا في اثنتين: رجل آتاه الله مالا فسلطه على هلكته في الحق ورجل آتاه الله الحكمة فهو يقضي بها ويعلمها» .\n(صحيح) [حم ق هـ] عن ابن مسعود. حم ١/٣٨٢، ٤٣٢، خ/٣٠، م ٢/٢٠١، هـ ٤٢٠٨."],[8126,"٢٦٦٠ - «لا حسد إلا في اثنتين: رجل علمه الله القرآن فهو يتلوه آناء الليل وآناء النهار فسمعه جار له فقال: ليتني أوتيت مثل ما أوتي فلان فعملت مثل ما يعمل ورجل آتاه الله مالا فهو يهلكه في الحق فقال رجل: ليتني أوتيت مثل ما أوتي فلان فعملت مثل ما يعمل» .\n(صحيح) [حم خ] عن أبي هريرة. حم ٢/٤٧٩، خ ٤/٤٠٩ - ٤١٠."],[8127,"(١) الأصل [اثنين] والتصحيح من المصادر المذكورة أعلاه."],[8128,"٢٦٦١ - «لا حلف في الإسلام وأيما حلف كان في الجاهلية لم يزده الإسلام إلا شدة» .\n(صحيح) [حم م د ن] عن جبير بن مطعم. مختصر مسلم ١٧٤٠."],[8129,"٢٦٦٢ - «لا حمى إلا لله ولرسوله» .\n(صحيح) [حم خ د] عن الصعب بن جثامة."],[8130,"«لا خير فيمن لا يضيف» .\n(صحيح) [حم هب] عن عقبة بن عامر. الصحيحة ٢٤٣٤: الروياني."],[8131,"٢٦٦٣ - «لا دعوة في الإسلام ذهب أمر الجاهلية الولد للفراش وللعاهر الحجر» .\n(صحيح) [حم د] عن ابن عمرو. المشكاة ٣٣٢٠."],[8132,"٢٦٦٤ - «لا ربا فيما كان يدا بيد» .\n(صحيح) [حم ق ن هـ] عن أسامة بن زيد. الإرواء ١٣٣٨، أحاديث البيوع."],[8133,"«لا رضاع إلا ما فتق الأمعاء» .\n(صحيح) [هـ] عن الزبير. الإرواء ٢١٥٠."],[8134,"«لا رقية إلا من عين أو حمة أو دم» .\n(صحيح) [م هـ] عن بريدة [حم د ت] عن عمران. المشكاة ٤٥٥٧."],[8135,"«لا زكاة في مال حتى يحول عليه الحول» .\n(صحيح) [هـ] عن عائشة. صحيح أبي داود ١٤٠٣، الإرواء ٧٨٧."],[8136,"«لا سبق إلا في خف أو حافر أو نصل» .\n(صحيح) [حم ٤] عن أبي هريرة. الروض النضير ١١٦٦، الإرواء ١٥٠٦، المشكاة ٣٨٧٤."],[8137,"«لا سمر إلا لمصل أو مسافر» .\n(صحيح) [حم] عن ابن مسعود. الصحيحة ٢٤٣٥: الطيالسي، ابن نصر، حل، خط."],[8138,"٢٦٦٥ - «لا شؤم وقد يكون اليمن في: الدار والمرأة والفرس» .\n(صحيح) [ت هـ] عن حكيم بن معاوية. الصحيحة ١٩٣٠: الطحاوي."],[8139,"٢٦٦٦ - «لا شغار في الإسلام» .\n(صحيح) [حم هـ حب] عن أنس [م] عن ابن عمر."],[8140,"«لا شيء أغير من الله تعالى» .\n(صحيح) [حم ق] عن أسماء بنت أبي بكر."],[8141,"٢٦٦٧ - «» * [......... العين حق وأصدق الطيرة الفأل] .\n(صحيح) \"حم ت عن حابس. الضعيفة ٤٨٠٤."],[8142,"٢٦٦٨ - «لا صاعي تمر بصاع ولا صاعي حنطة بصاع ولا درهمين بدرهم» .\n(صحيح) [ن حب] عن أبي سعيد. أحاديث البيوع."],[8143,"«لا صاعين بصاع ولا درهمين بدرهم» .\n(صحيح) [ق ن] عن أبي سعيد. أحاديث البيوع."],[8144,"٢٦٧٠ - «لا صام من صام الأبد» .\n(صحيح) [ق ن هـ] عن ابن عمرو. مختصر مسلم ٦٢٨."],[8145,"٢٦٧١ - «لا صام من صام الدهر صوم ثلاثة أيام صوم الدهر كله» .\n(صحيح) [خ] عن ابن عمرو."],[8146,"٢٦٧٢ - \"لا صوم فوق صوم داود شطر الدهر صم يوما وأفطر يوما\".\n(صحيح) [خ ن] عن ابن عمرو."],[8147,"(*) أوله [لا شيء في البهائم] . وقد ضعف شيخنا الألباني هذا القسم من الحديث، انظر [ضعيف الجامع] ٦٣٠٩ والحديث في مسند أحمد ٥/٧٠ عن حابس التميمي."],[8148,"«لا صلاة بحضرة طعام ولا وهو يدافعه الأخبثان» .\n(صحيح) [م د] عن عائشة. الإرواء ٥٥٠."],[8149,"«لا صلاة بعد الصبح حتى ترتفع الشمس ولا صلاة بعد العصر حتى تغرب الشمس» .\n(صحيح) [ق ن هـ] عن أبي سعيد [حم د هـ] عن عمر. الروض النضير ١١٦٧، الإرواء ٤٧٩، صحيح أبي داود ١١٥٧: ق، أبو عوانة، ن، ت - عمر."],[8150,"٢٦٧٣ - «لا صلاة بعد الفجر إلا سجدتين» .\n(صحيح) [ت] عن ابن عمر. الإرواء ٤٧٨."],[8151,"٢٦٧٤ - «لا صلاة لمن لم يقرأ بأم القرآن فصاعدا» .\n(صحيح) [م د ن] عن عبادة بن الصامت. صحيح أبي داود ٧٨٠، الإرواء ٣٠٢."],[8152,"«لا صلاة لمن لم يقرأ بفاتحة الكتاب» ... [حم ق ٤] عن عبادة.\n(صحيح) الروض النضير ٣٦٤، الإرواء ٣٠٢، صحيح أبي داود ٧٨٠."],[8153,"٢٦٧٥ - «لا صلاة لمن لا وضوء له ولا وضوء لمن لم يذكر اسم الله عليه» ... [حم د هـ ك] عن أبي هريرة [هـ] عن سعيد بن زيد.\n(صحيح) الإرواء ٨١، المشكاة ٤٠٤."],[8154,"٢٦٧٦ - «لا صلاة لمن لا وضوء له ولا وضوء لمن لم يذكر اسم الله عليه، ... ...» .\n(صحيح) [هـ ك] عن سهل بن سعد. الضعيفة ٢١٦٦، ٤٨٠٦."],[8155,"٢٦٧٧ - «لا صيام لمن لم يفرضه من الليل» .\n(صحيح) [هـ] عن حفصة. الإرواء ٩١٤."],[8156,"«لا ضرر ولا ضرار» .\n(صحيح) [حم هـ] عن ابن عباس [هـ] عن عبادة. الإرواء ٨٩٦، الصحيحة ٢٥٠."],[8157,"«لا ضمان على مؤتمن» .\n(حسن) [هق] عن ابن عمرو. الإرواء ١٥٤٧."],[8158,"«لا طاعة لأحد في معصية الله إنما الطاعة في المعروف» .\n(صحيح) [ق ن] عن علي. الصحيحة ١٨١: الطيالسي، حم."],[8159,"«لا طاعة لمخلوق في معصية الخالق» .\n(صحيح) [حم ك] عن عمران والحكم بن عمرو الغفاري. الصحيحة ١٧٩، المشكاة ٣٦٩٦: الطيالسي، طب."],[8160,"«لا طاعة لمن لم يطع الله» .\n(صحيح) [حم] عن أنس. ٣/٢١٣."],[8161,"٢٦٧٨ - «لا طلاق إلا فيما يملك ولا عتق إلا فيما يملك ولا بيع إلا فيما يملك ولا وفاء نذر إلا فيما يملك ولا نذر إلا فيما ابتغي به وجه الله ومن حلف على معصية فلا يمين له ومن حلف على قطيعة رحم فلا يمين له» .\n(حسن) [د ك] عن ابن عمرو. المشكاة ٣٢٨٢، الإرواء ١٧٥١."],[8162,"٢٦٧٩ - «لا طلاق قبل النكاح» .\n(صحيح) [هـ] عن علي [ك] عن جابر. الإرواء ٢٠٧٠."],[8163,"«لا طلاق قبل النكاح ولا عتاق قبل ملك» .\n(صحيح) [هـ] عن المسور. الإرواء ٢٠٧٠."],[8164,"«لا طلاق ولا عتاق في إغلاق» .\n(حسن) [حم د هـ ك] عن عائشة. المشكاة ٣٢٨٥، الإرواء ٢٠٤٧."],[8165,"٢٦٨٠ - «لا طيرة وخيرها الفأل: الكلمة الصالحة يسمعها أحدكم» .\n(صحيح) [حم م] عن أبي هريرة."],[8166,"«لا عدوى ولا صفر ولا هامة» .\n(صحيح) [حم ق] عن أبي هريرة [حم م] عن السائب بن يزيد. مختصر مسلم ١٤٨٦، الصحيحة ٧٨٣، ٧٨٤، السنة ٢٧٠، ٢٧١ - ٢٧٦، ٢٨٤ ابن أبي عاصم."],[8167,"٢٦٨١ - «لا عدوى ولا طيرة وإنما الشؤم في ثلاث: في١ الفرس والمرأة والدار» .\n(صحيح) [حم ق] عن ابن عمر. مختصر مسلم ١٤٩٢، الصحيحة ٧٨٨."],[8168,"٢٦٨٢ - «لا عدوى ولا طيرة ولا هامة،.... فمن أجرب الأول» .\n(صحيح) [حم هـ] عن ابن عمر. الضعيفة ٤٨٠٨."],[8169,"٢٦٨٣ - «لا عدوى ولا طيرة ولا هامة ولا صفر وفر من المجذوم كما تفر من الأسد» .\n(صحيح) [حم خ] عن أبي هريرة. الصحيحة ٧٨٤."],[8170,"«لا عدوى ولا طيرة ولا هامة ولا صفر ولا غول» ... [حم م] عن جابر.\n(صحيح) مختصر مسلم ١٤٨٩، الصحيحة ٧٨٤، السنة ٢٦٨و ٢٨١: ابن أبي عاصم."],[8171,"٢٦٨٤ - «لا عدوى ولا طيرة ويعجبني الفأل الصالح والفأل الصالح: الكلمة الحسنة» .\n(صحيح) [حم ق د ت هـ] عن أنس. الصحيحة ٧٧٦."],[8172,"٢٦٨٥ - «لا عدوى ولا هامة ولا طيرة وأحب الفأل الحسن» .\n(صحيح) [م] عن أبي هريرة. الصحيحة ٧٨٧."],[8173,"(١) وفي رواية لـ[خ]: [إن كان الشؤم في شيء ففي.. ...] وهي الراجحة عندي كما بينته في المصدر المذكور أعلاه رقم ١٤٢٧، ويأتي له شاهد برقم ٧٥٦٢."],[8174,"٢٦٨٦ - «لا عدوى ولا هامة ولا نوء ولا صفر» .\n(صحيح) [د] عن أبي هريرة. مختصر مسلم ١٤٨٨، إصلاح المساجد ٩٠، السنة ٢٧٥: حم، م، ابن أبي عاصم."],[8175,"«لا عقر١ في الإسلام» .\n(صحيح) [د] عن أنس. الصحيحة ٢٤٣٦: حم، حل، الرامهرمزي."],[8176,"٢٦٨٧ - «لا عقوبة فوق عشر ضربات إلا في حد من حدود الله» .\n(صحيح) [خ] عن رجل."],[8177,"٢٦٨٨ - «لا عليكم أن لا تفعلوا فإن الله تعالى كتب من هو خالق إلى يوم القيامة» .\n(صحيح) [حم م] عن أبي سعيد. الصحيحة ١٠٣٢."],[8178,"٢٦٨٩ - «لا عليكم أن لا تفعلوا ما كتب الله خلق نسمة هي كائنة إلى يوم القيامة إلا ستكون» .\n(صحيح) [م د] عن أبي سعيد. الصحيحة ١٠٣٢."],[8179,"٢٦٩٠ - «لا عمرى فمن أعمر شيئا فهو له» .\n(صحيح) [حم ن هـ] عن أبي هريرة. الإرواء ١٦٠٧."],[8180,"٢٦٩١ - «لا عمرى ولا رقبى فمن أعمر شيئا أو أرقبه فهو له في حياته ومماته» .\n(صحيح) [حم ن هـ] عن ابن عمر. الإرواء ١٦٠٩: حم، ابن الجارود."],[8181,"«لا غرار٢ في صلاة ولا تسليم» .\n(صحيح) [حم د ك] عن أبي هريرة. الصحيحة ٣١٨، صحيح أب داود ٨٦١."],[8182,"(١) أي لا ذبح عند القبر، وفي معناه التصدق عنده بخبز ونحوه. كذا في [فيض القدير] .٢ الغرار: النقصان، وغرار الصلاة أركانها وهيآتها. وغرار [التسليم] أن يقول المجيب: وعليك. ولا يقول: السلام عليك. وقيل غير ذلك. راجع [الصحيحة] ."],[8183,"«لا غصب ولا نهبة» ١.\n(صحيح) [طب] عن عمرو بن عوف."],[8184,"«لا غول» ... [د] عن أبي هريرة.\n(صحيح) الصحيحة ٧٨٤، السنة ٢٦١ - ٢٨١: حم، م، الطحاوي - جابر."],[8185,"«لا فرع ولا عتيرة» .\n(صحيح) [حم ق ٤] عن أبي هريرة. مختصر مسلم ١٢٦٠، الإرواء ١١٨٠."],[8186,"«لا قطع في ثمر ولا كثر» .\n(صحيح) [حم ٤ حب] عن رافع بن خديج. الإرواء ٢٤١٤."],[8187,"٢٦٩٢ - «لا نذر في معصية الله ولا فيما لا يملك ابن آدم» .\n(صحيح) [ن هـ] عن عمران بن حصين. حم ٤/٤٣٣، م ٥/٧٨ - ٧٩."],[8188,"«لا نذر في معصية وكفارته كفارة يمين» .\n(صحيح) [حم ٤] عن عائشة [ن] عن عمران بن حصين. المشكاة ٣٤٣٥، الإرواء ٢٥٨٧، ٢٥٩٠: الطحاوي، هق، خط."],[8189,"٢٦٩٣ - «لا نذر لابن آدم فيما لا يملك ولا يمين له فيما لا يملك ولا طلاق له فيما لا يملك» .\n(حسن) [ت] عن ابن عمرو. الإرواء ١٧٥١."],[8190,"٢٦٩٤ - «لا نذر ولا يمين فيما لا يملك ابن آدم ولا في معصية الله ولا في قطيعة رحم، ... ...» .\n(صحيح) [د ك] عن ابن عمرو. الضعيفة ١٣٦٥."],[8191,"(١) قلت: هو بمعنى الحديث السابق: [نهى عن النهبة والخلسة] رقم ٦٩١٨."],[8192,"٢٦٩٥ - «لا نفقة لك إلا أن تكوني حاملا» .\n(صحيح) [د] عن فاطمة بنت قيس. الإرواء ٢١٦٠."],[8193,"٢٦٩٦ - «لا نفقة لك ولا سكنى» .\n(صحيح) [م] عن فاطمة بنت قيس. الإرواء ٢١٦٠."],[8194,"٢٦٩٧ - «لا نفل إلا بعد الخمس» .\n(صحيح) [حم د] عن معن بن يزيد. المشكاة ٤٠٠٩."],[8195,"٢٦٩٨ - «لا نقطع الأبطح إلا شدا» .\n(صحيح) [حم هـ] عن أم ولد شيبة. الصحيحة ٢٤٣٧."],[8196,"٢٦٩٩ - «لا نقطع الوادي إلا شدا» .\n(صحيح) [ن] عن امرأة صحابية. المصدر نفسه."],[8197,"«لا نكاح إلا بولي» .\n(صحيح) [حم ٤ ك] عن أبي موسى [هـ] عن ابن عباس. الإرواء ١٨٣٩."],[8198,"٢٧٠٠ - «لا نكاح إلا بولي والسلطان ولي من لا ولي له» .\n(صحيح) [حم هـ] عن عائشة. المصدر نفسه."],[8199,"«لا نكاح إلا بولي وشاهدي عدل» .\n(صحيح) [هق] عن عمران وعائشة. الإرواء ١٨٣٩، ١٨٥٨، ١٨٦٠."],[8200,"«لا نكاح إلا بولي وشاهدين» .\n(صحيح) [طب] عن أبي موسى. الإرواء ١٨٣٩، ١٨٥٨."],[8201,"٢٧٠١ - «لا نورث ما تركنا صدقة» .\n(صحيح) [حم ق ٣] عن عمر وعثمان وسعد وطلحة والزبير وعبد الرحمن بن عوف [حم ق] عن عائشة [م ت] عن أبي هريرة. مختصر مسلم ١١٤٧، الصحيحة ٢٠٣٨."],[8202,"٢٧٠٢ - \"لا نورث ما تركنا صدقة وإنما يأكل آل محمد، في هذا المال\".\n(صحيح) [حم ق د ن] عن أبي بكر. مختصر مسلم ١١٤٨، الصحيحة ٢٠٣٨."],[8203,"٢٧٠٣ - «لا نورث ما تركنا فهو صدقة وإنما هذا المال لآل محمد لنائبتهم ولضيفهم فإذا مت فهو إلى ولي الأمر من بعدي» .\n(صحيح) [د] عن عائشة. الصحيحة ٢٠٣٨. ٧٥٦٢* - ٢٧٠٤ -[لا هامة ولا عدوى ولا طيرة وإن تكن الطيرة في شيء ففي: الفرس والمرأة والدار] . (صحيح) [حم] عن سعد بن مالك. الصحيحة ٨٧٩."],[8204,"٢٧٠٥ - «لا هجرة بعد الفتح ولكن جهاد ونية وإذا استنفرتم فانفروا» .\n(صحيح) [م] عن عائشة [حم ن] عن صفوان بن أمية [حم ت ن] عن ابن عباس. مختصر مسلم ١١٨٦، الإرواء ١١٨٧، ١٢٠٩."],[8205,"«لا هجرة بعد ثلاث» .\n(صحيح) [حم م] عن أبي هريرة. الإرواء ٢٠٢٩."],[8206,"«لا هجرة بعد فتح مكة» .\n(صحيح) [خ] عن مجاشع بن مسعود. الإرواء ١١٨٧."],[8207,"٢٧٠٦ - «لا هجرة ولكن جهاد ونية وإذا استنفرتم فانفروا فإن هذا بلد حرمه الله يوم خلق السموات والأرض وهو حرام بحرمة الله إلى يوم القيامة وإنه لم يحل القتال فيه لأحد قبلي ولا يحل لي إلا ساعة من نهار فهو حرام بحرمة الله إلى يوم القيامة لا يعضد شوكه ولا ينفر صيده ولا يلتقط لقطته إلا من عرفها ولا يختلى خلاها إلا الإذخر» .\n(صحيح) [حم ق د ت] عن ابن عباس. الإرواء ١٠٥٧."],[8208,"(*) هذه الأحاديث الخمسة ٧٥٦٢ - ٧٥٦٦ كانت في الأصل بعد الحديث ٧٥٧٤ فنقلتها إلى هنا لأنه اللائق بالترتيب - زهير."],[8209,"«لا وتران في ليلة» ... [حم ٣ الضياء] عن طلق بن علي.\n(صحيح) صحيح أبي داود ١٢٩٣: الطيالسي، ابن أبي شيبة، حب، هق."],[8210,"٢٧٠٧ - «لا وجدته لا وجدته لا وجدته إنما بنيت هذه المساجد لما بنيت له» .\n(صحيح) [حم م ن هـ] عن بريدة."],[8211,"«لا وصال في الصوم» .\n(صحيح) [الطيالسي] عن جابر. الطيالسي ١٧٦٤، ١٧٦٥. حم ٣/٦٢ - أبي سعيد١."],[8212,"«لا وصية لوارث» .\n(صحيح) [قط] عن جابر. الإرواء ١٦٥٥."],[8213,"٢٧٠٨ - «لا وضوء إلا من ريح أو سماع» .\n(صحيح) [حم هـ] عن السائب بن خباب. المشكاة ٣٠٠."],[8214,"«لا وضوء إلا من صوت أو ريح» .\n(صحيح) [ت هـ] عن أبي هريرة. الروض النضير ٣١٠، المشكاة ٣٠٠."],[8215,"٢٧٠٩ - «لا وضوء لمن لم يذكر اسم الله عليه» .\n(صحيح) [ت] عن سعيد بن زيد [ت في العلل] عن أبي هريرة [حم ت في العلل هـ ك] عن أبي سعيد. المشكاة ٤٠٤."],[8216,"«لا وفاء لنذر في معصية الله» .\n(صحيح) [حم] عن جابر. حم ٤/٤٣٣ - ٤٣٤، م ٥/٧٨ - ٧٩ - عمران."],[8217,"«لا يأتي رجل مولاه فيسأله من فضل هو عنده فيمنعه إياه إلا دعي له يوم القيامة شجاع أقرع يتلمظ فضله الذي منع منه» .\n(حسن) [ن] عن معاوية بن حيدة. الصحيحة ٢٤٣٨: حم."],[8218,"(١) قلت: وراه البخاري وغيره عنه نحوه، ومضى برقم ٧٤٧٧."],[8219,"«لا يأتي عليكم عام ولا يوم إلا والذي بعده شر منه حتى تلقوا ربكم» .\n(صحيح) [حم خ هـ] عن أنس. الصحيحة ١/١٠."],[8220,"٢٧١١ - «لا يأخذ أحد شبرا من الأرض بغير حقه إلا طوقه الله إلى سبع أرضين يوم القيامة» .\n(صحيح) [م] عن أبي هريرة."],[8221,"٢٧١٢ - «لا يأخذن أحدكم متاع صاحبه لاعبا ولا جادا وإن أخذ عصا صاحبه فليردها عليه» .\n(حسن) [حم د ت ك] عن السائب بن يزيد. المشكاة ٢٩٤٨، الإرواء ١٥١٨."],[8222,"٢٧١٣ - «لا يأكل أحدكم بشماله ولا يشرب بشماله فإن الشيطان يأكل بشماله ويشرب بشماله» .\n(صحيح) [م ت] عن ابن عمر. الصحيحة ١٢٣٦: حم، خد."],[8223,"٢٧١٤ - «لا يأكل أحدكم من لحم أضحيته فوق ثلاثة أيام» .\n(صحيح) [حم م ت] عن ابن عمر. الإرواء ١١٥٥."],[8224,"٢٧١٥ - «لا يؤم الرجل في سلطانه ولا يجلس على تكرمته في بيته إلا بإذنه» .\n(صحيح) [ت] عن ابن مسعود. صحيح أبي داود ٥٩٤، الإرواء ٤٩٤: حم، م١."],[8225,"«لا يؤمن أحدكم حتى أكون أحب إليه من ولده ووالده والناس أجمعين» .\n(صحيح) [حم ق ن هـ] عن أنس. مختصر مسلم ٢٣."],[8226,"(١) قلت: ويأتي حديثهم بلفظ: [يؤم القوم.. ...] ."],[8227,"«لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه» .\n(صحيح) [حم ق ت ن هـ] عن أنس. مختصر مسلم ٢٤، الصحيحة ٧٣."],[8228,"٢٧١٦ - «لا يؤمن عبد حتى يؤمن بأربع: يشهد أن لا إله إلا الله وأني رسول الله بعثني بالحق ويؤمن بالموت ويؤمن بالبعث بعد الموت ويؤمن بالقدر خيره وشره» ... [حم ت هـ ك] عن علي.\n(صحيح) المشكاة ١٠٤، السنة ١٣٠و ٨٨٧: حب، ابن أبي عاصم."]])